(function(A){Object.assign(A.D,{"G3004":{"l":"λέγω","o":2335,"ar":"<f><o>λέγω</o>،</f> <s> <s n=\"1.\">في اليونانية الكلاسيكية: أصلاً، <b>يلتقط</b>، <b>يجمع</b>، <b>يعدّ</b>، <b>يسرد</b>.</s> <s n=\"2.\"><b>يقول</b>، <b>يتكلم</b>، <b>يؤكد</b>، <b>يُعلن</b>: مطلقًا، <r v=\"Acts.13.15\"></r> <r v=\"Acts.24.10\"></r>؛ يليه كلام مباشر، <r v=\"Matt.9.34\"></r>، <r v=\"Mark.3.11\"></r>، <r v=\"John.1.29\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g> لنقل الكلام، <r v=\"Mark.3.21\"></r>، <r v=\"Luke.1.24\"></r>، <r v=\"John.6.14\"></r>، وفي مواضع أخرى؛ مع المنصوب والمصدر، <r v=\"Luke.11.18\"></r>، <r v=\"John.12.29\"></r>، وفي مواضع أخرى؛ بعد فعل آخر من أفعال الكلام، <g>προσφωνεῖν κ. λέγειν</g>، <r v=\"Matt.11.17\"></r>، وفي مواضع أخرى؛ <g>ἀπεκρίθη</g> (<g>ἐλάλησεν</g>) <g>λέγων</g> (<g>καὶ λέγει</g>)، <r v=\"Matt.25.9\"></r>، <r v=\"Mark.3.33\"></r>، <r v=\"Mark.7.28\"></r>، <r v=\"Luke.24.6\"></r>، <r v=\"Luke.24.7\"></r>، وفي مواضع أخرى؛ عن الفكر غير المنطوق، <g>λ. ἐν ἑαυτῷ</g>، <r v=\"Matt.3.9\"></r>، <r v=\"Luke.3.8\"></r>، وفي مواضع أخرى؛ عن الكتابة، <r v=\"2Cor.8.8\"></r>، <r v=\"Phil.4.11\"></r>، وفي مواضع أخرى؛ <g>λέγει ἡ γραφή</g>، <r v=\"Rom.4.3\"></r>، <r v=\"Jas.2.23\"></r>، وفي مواضع أخرى؛ مع منصوب الشيء، <r v=\"Luke.8.8\"></r> <r v=\"Luke.9.33\"></r>، <r v=\"John.5.34\"></r>، وفي مواضع أخرى؛ <g>σὺ λέγεις</g> (عبارة لا تُلزِم القائل بموقف)، <r v=\"Matt.27.11\"></r>، <r v=\"Mark.15.2\"></r>، <r v=\"Luke.23.3\"></r>، <r v=\"John.18.37\"></r>؛ مع قابل الشخص، يليه كلام مباشر، <r v=\"Matt.8.20\"></r>، <r v=\"Mark.2.17\"></r>، وفي مواضع أخرى كثيرة؛ والتعبير نفسه يليه <g>ὅτι</g>، <r v=\"Matt.3.9\"></r>، وفي مواضع أخرى؛ مع حرف جر، <g>πρός</g>، <g>μετά</g>، <g>περί</g>، إلخ، <r v=\"Mark.4.41\"></r>، <r v=\"John.11.56\"></r>، <r v=\"Heb.9.5\"></r>، وفي مواضع أخرى؛ <b>يعني</b>، <r v=\"Mark.14.71\"></r>، <r v=\"John.6.71\"></r>، <r v=\"1Cor.10.29\"></r>، وفي مواضع أخرى؛ <b>يدعو</b>، <b>يُسمّي</b>، <r v=\"Mark.10.18\"></r>؛ المبني للمجهول، <r v=\"Matt.9.9\"></r>، <r v=\"Mark.15.7\"></r>، وفي مواضع أخرى (قارن <g>ἀντι-</g>، <g>δια-</g> (<g>-μαι</g>)، <g>προ-</g>، <g>συλ-λέγω</g>).</s> </s>","en":"<f><o>λέγω</o>,</f> <et> <e t=\"septuagint\">[in LXX very freq., chiefly for <h n=\"H559\">אמר</h>; <g>λέγει</g> for <h n=\"H5002\">נְאֻם</h>, <r v=\"Gen.22.16\"></r>, al.;]</e> </et> <s> <s n=\"1.\">in Hom., <b>to pick out</b>, <b>gather</b>, <b>reckon</b>, <b>recount</b>.</s> <s n=\"2.\">In Hdt. and Att., <b>to say</b>, <b>speak</b>, <b>affirm</b>, <b>declare</b>: absol., <r v=\"Acts.13.15\"></r> <r v=\"Acts.24.10\"></r>; seq. orat. dir., <r v=\"Matt.9.34\"></r>, <r v=\"Mark.3.11\"></r>, <r v=\"John.1.29\"></r>, al.; seq. <g>ὅτι</g> recit., <r v=\"Mark.3.21\"></r>, <r v=\"Luke.1.24\"></r>, <r v=\"John.6.14\"></r>, al.; acc. et. inf., <r v=\"Luke.11.18\"></r>, <r v=\"John.12.29\"></r>, al.; after another verb of speaking, <g>προσφωνεῖν κ. λέγειν</g>, <r v=\"Matt.11.17\"></r>, al.; <g>ἀπεκρίθη</g> (<g>ἐλάλησεν</g>) <g>λέγων</g> (<g>καὶ λέγει</g>; Dalman, <i>Words</i>, 24 ff.), <r v=\"Matt.25.9\"></r>, <r v=\"Mark.3.33\"></r>, <r v=\"Mark.7.28\"></r>, <r v=\"Luke.24.6\"></r>, <r v=\"Luke.24.7\"></r>, al.; of unspoken thought, <g>λ. ἐν ἑαυτῷ</g>, <r v=\"Matt.3.9\"></r>, <r v=\"Luke.3.8\"></r>, al.; of writing, <r v=\"2Cor.8.8\"></r>, <r v=\"Phil.4.11\"></r>, al.; <g>λέγει ἡ γραφή</g>, <r v=\"Rom.4.3\"></r>, <r v=\"Jas.2.23\"></r>, al.; c. acc. rei, <r v=\"Luke.8.8\"></r> <r v=\"Luke.9.33\"></r>, <r v=\"John.5.34\"></r>, al.; <g>σὺ λέγεις</g> (a non-committal phrase; Swete, <i>Mk.</i>, 359, 369 f.), <r v=\"Matt.27.11\"></r>, <r v=\"Mark.15.2\"></r>, <r v=\"Luke.23.3\"></r>, <r v=\"John.18.37\"></r>; c. dat. pers., seq. orat. dir., <r v=\"Matt.8.20\"></r>, <r v=\"Mark.2.17\"></r>, al. mult.; id. seq. <g>ὅτι</g>, <r v=\"Matt.3.9\"></r>, al.; c. prep., <g>πρός</g>, <g>μετά</g>, <g>περί</g>, etc., <r v=\"Mark.4.41\"></r>, <r v=\"John.11.56\"></r>, <r v=\"Heb.9.5\"></r>, al.; <b>to mean</b> (cl.), <r v=\"Mark.14.71\"></r>, <r v=\"John.6.71\"></r>, <r v=\"1Cor.10.29\"></r>, al.; <b>to call</b>, <b>name</b>, <r v=\"Mark.10.18\"></r>; pass., <r v=\"Matt.9.9\"></r>, <r v=\"Mark.15.7\"></r>, al (cf. <g>ἀντι-</g>, <g>δια-</g> (<g>-μαι</g>), <g>προ-</g>, <g>συλ-λέγω</g>).</s> </s> <sy><i>SYN.</i>: <g>λαλέω</g>, which refers to the utterance, as <g>λέγω</g> to the meaning of what is said, its correspondence with thought (Tr., <i>Syn.</i>, Ixxvi; Thayer, s.v. <g>λαλέω</g>).</sy>"},"G3065":{"l":"Λουκᾶς","o":3,"ar":"<f><o>Λουκᾶς</o>، <g>-ᾶ, ὁ</g></f> <s><b>لوقا</b>: لوقا، <i>العنوان</i>، <r v=\"Col.4.14\"></r>، <r v=\"2Tim.4.11\"></r>، <r v=\"Phlm.1.24\"></r>.†</s>","en":"<f><o>Λουκᾶς</o>, <g>-ᾶ, ὁ</g></f> <et> <e t=\"derivation\">(prob. an abbreviation of <g>Λουκανός</g>; v. Lft., <i>Col.</i>, 240; <i>ICC</i>, <i>Lk.</i>, xviii; Bl., § 29; acc. to Ramsay, <i>Exp.</i>, Dec., 1912, pp. 502 ff., a by-form of <g>Λούκιος</g>, from Lat. <l>Lucius</l>),</e> </et> <s><b>Luke</b>: Lk, <i>tit.</i>, <r v=\"Col.4.14\"></r>, <r v=\"2Tim.4.11\"></r>, <r v=\"Phlm.1.24\"></r>.†</s>"},"G3056":{"l":"λόγος","o":330,"ar":"<f><o>λόγος</o>، <g>-ου, ὁ</g> (مشتقة من <g>λέγω</g>)،</f> <s> <s n=\"I.\">عمّا يُعبَّر به عن الفكر الداخلي، باللاتينية <l>oratio</l>، <l>sermo</l>، <l>vox</l>، <l>verbum</l>. <s n=\"1.\"><b>كلمة</b>، لا بالمعنى النحوي لمجرد اسم (<g>ἔπος</g>، <g>ὄνομα</g>، <g>ῥῆμα</g>)، بل كلمة بوصفها حاملةً لمفهوم أو فكرة: <r v=\"Matt.8.8\"></r>، <r v=\"Luke.7.7\"></r>، <r v=\"1Cor.14.9\"></r>، <r v=\"1Cor.14.19\"></r>، <r v=\"Heb.12.19\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\"><b>قول</b>، <b>عبارة</b>، <b>تصريح</b>: <r v=\"Matt.19.22\"></r>، <r v=\"Mark.5.36\"></r> <r v=\"Mark.7.29\"></r>، <r v=\"Luke.1.29\"></r>، <r v=\"John.2.22\"></r> <r v=\"John.6.60\"></r>، <r v=\"Acts.7.29\"></r>، وفي مواضع أخرى؛ مع مضاف إليه وصفي، <r v=\"Acts.13.15\"></r>، <r v=\"Rom.9.9\"></r>، <r v=\"Heb.7.28\"></r>، وفي مواضع أخرى؛ عن أقوال المعلّمين ووصاياهم ومواعيدهم، إلخ.، <r v=\"Matt.7.24\"></r> <r v=\"Matt.10.14\"></r>، <r v=\"Mark.8.38\"></r>، <r v=\"Luke.9.44\"></r>، <r v=\"John.14.24\"></r>، وفي مواضع أخرى؛ <g>λ. κενοί</g>، <r v=\"Eph.5.6\"></r>؛ <g>ἀληθινοί</g>، <r v=\"Rev.19.9\"></r>؛ <g>πιστοί</g>، <r v=\"Rev.22.6\"></r>؛ خاصةً عن وصايا الله وأحكامه ومواعيده، <g>ὁ λ. τ. θεοῦ</g>، <b>كلمة الله</b>: <r v=\"Mark.7.13\"></r>، <r v=\"John.10.35\"></r>، <r v=\"Rom.13.9\"></r>، <r v=\"1Cor.14.36\"></r>، <r v=\"Phil.1.14\"></r>، وفي مواضع أخرى؛ مطلقًا، <g>ὁ λ.</g>، <r v=\"Matt.13.21\"></r>، <r v=\"Matt.13.22\"></r>، <r v=\"Mark.16.20\"></r>، <r v=\"Luke.1.2\"></r>، <r v=\"Acts.6.4\"></r>، <r v=\"Heb.4.12\"></r>، وفي مواضع أخرى.</s> <s n=\"3.\"><b>كلام</b>، <b>خطاب</b>: <r v=\"Acts.14.12\"></r>، <r v=\"2Cor.10.10\"></r>، <r v=\"Jas.3.2\"></r>؛ عكس <g>ἐπιστολή</g>، <r v=\"2Thess.2.15\"></r>؛ مميَّزًا عن <g>σοφία</g>، <r v=\"1Cor.2.1\"></r>؛ <g>ἀναστροφή</g>، <r v=\"1Tim.4.12\"></r>؛ <g>δύναμις</g>، <r v=\"1Cor.4.19\"></r>، <r v=\"1Thess.1.5\"></r>؛ <g>ἔργον</g>، <r v=\"Rom.15.18\"></r>؛ <g>οὐδενὸς λ. τίμιον</g> (<i>لا يستحق الذكر</i>)، <r v=\"Acts.20.24\"></r>؛ عن ملَكة النطق، <r v=\"Luke.24.19\"></r>، <r v=\"2Cor.11.6\"></r>؛ عن أسلوب الكلام، <r v=\"Matt.5.37\"></r>، <r v=\"1Cor.1.5\"></r>؛ عن التعليم، <r v=\"Col.4.3\"></r>، <r v=\"1Pet.3.1\"></r>؛ مع مضاف إليه الشخص، <r v=\"John.5.24\"></r> <r v=\"John.8.52\"></r>، <r v=\"Acts.2.41\"></r>، وفي مواضع أخرى؛ <g>ὁ λ. ὁ ἐμός</g>، <r v=\"John.8.31\"></r>؛ مع مضاف إليه مفعولي (<g>τ.</g>) <g>ἀληθείας</g>، <r v=\"2Cor.6.7\"></r>، <r v=\"Col.1.5\"></r>، <r v=\"Jas.1.18\"></r>؛ <g>τ. καταλλαγῆς</g>، <r v=\"2Cor.5.19\"></r>؛ <g>τ. σταυροῦ</g>، <r v=\"1Cor.1.18\"></r>؛ عن مجرد الكلام، <r v=\"1Cor.4.19\"></r>، <r v=\"1Cor.4.20\"></r>، <r v=\"Col.2.23\"></r>، <r v=\"1John.3.18\"></r>؛ عن الكلام الذي يُثيره المرء (بين الناس)، ومن ثمّ، <b>سُمعة</b>: <r v=\"Col.2.23\"></r>.</s> <s n=\"4.\"><b>موضوع (مادة الكلام)</b>، ومن ثمّ، <b>تعليم</b>، <b>عقيدة</b>: <r v=\"Acts.18.15\"></r>، <r v=\"2Tim.2.17\"></r>، وفي مواضع أخرى؛ خاصةً عن التعليم المسيحي: <r v=\"Matt.13.20-Matt.13.23\"></r>، <r v=\"Mark.4.14-Mark.4.20\"></r> <r v=\"Mark.8.32\"></r>، <r v=\"Luke.1.2\"></r>، <r v=\"Acts.8.4\"></r>، <r v=\"Gal.6.6\"></r>، <r v=\"1Thess.1.6\"></r>، وفي مواضع أخرى؛ مع مضاف إليه الشخص، <g>τ. θεοῦ</g>، <r v=\"Luke.5.1\"></r>، <r v=\"John.17.6\"></r>، <r v=\"Acts.4.29\"></r>، <r v=\"1Cor.14.36\"></r>، <r v=\"1John.1.10\"></r>، <r v=\"Rev.6.9\"></r>، وفي مواضع أخرى؛ <g>τ. Κυρίου</g>، <r v=\"Acts.8.25\"></r>، <r v=\"1Thess.1.8\"></r>، وفي مواضع أخرى؛ <g>τ. Χριστοῦ</g>، <r v=\"Col.3.16\"></r>، <r v=\"Rev.3.8\"></r>؛ مع مضاف إليه بَدَلي، <r v=\"Acts.15.7\"></r>؛ مع مضاف إليه وصفي، <r v=\"Heb.5.13\"></r>.</s> <s n=\"5.\"><b>قصة</b>، <b>حكاية</b>، <b>رواية</b>: <r v=\"Matt.28.15\"></r>، <r v=\"John.21.23\"></r>، <r v=\"Acts.1.1\"></r> <r v=\"Acts.11.22\"></r>؛ «يليه» <g>περί</g>، <r v=\"Luke.5.15\"></r>.</s> <s n=\"6.\">ما يُتكلَّم عنه، <b>مسألة</b>، <b>أمر</b>، <b>شيء</b>: <r v=\"Matt.21.24\"></r>، <r v=\"Mark.1.45\"></r> <r v=\"Mark.11.29\"></r>، <r v=\"Luke.20.3\"></r>، <r v=\"Acts.8.21\"></r>؛ عن مسألة متنازَع عليها، كقضية أو دعوى قضائية، <r v=\"Acts.19.38\"></r>؛ جمع (<r v=\"1Macc.7.33\"></r>، وفي مواضع أخرى)، <r v=\"Luke.1.4\"></r>.</s> </s> <s n=\"II.\">عن الفكر الداخلي نفسه، باللاتينية <l>ratio</l>. <s n=\"1.\"><b>عقل</b>، <s n=\"(a)\">عن الملَكة الذهنية: <g>κατὰ λόγον</g>، <r v=\"Acts.18.14\"></r>؛</s> <s n=\"(b)\"><b>سبب</b>، <b>علّة</b>: <g>τίνι λόγῳ</g>، <r v=\"Acts.10.29\"></r>؛ <g>παρεκτὸς λόγου πορνείας</g>، <r v=\"Matt.5.32\"></r> <r v=\"Matt.19.9\"></r>.</s> </s> <s n=\"2.\"><b>اعتبار (حساب)</b>، <s n=\"(a)\"><b>اعتداد (اهتمام)</b>: <r v=\"Acts.20.24\"></r>؛</s> <s n=\"(b)\"><b>حساب</b>: <r v=\"Phil.4.15\"></r>، <r v=\"Phil.4.16\"></r>؛ <g>συναίρειν</g> (انظره) <g>λ.</g>، <r v=\"Matt.18.23\"></r> <r v=\"Matt.25.19\"></r>؛ بالمعنى القضائي، <r v=\"Rom.14.12\"></r>، <r v=\"Heb.13.17\"></r>، <r v=\"1Pet.4.5\"></r>؛ مع مضاف إليه الشيء، <r v=\"Luke.16.2\"></r>؛ «يليه» <g>περί</g>، <r v=\"Matt.12.36\"></r>، <r v=\"Acts.19.40\"></r>، <r v=\"1Pet.3.15\"></r>.</s> </s> <s n=\"3.\"><b>نسبة</b>، <b>تناسب (قياس)</b>: <r v=\"Phil.2.16\"></r>.</s> </s> <s n=\"III.\"><g>ὁ λ.</g>، <b>الكلمة</b> الإلهي أو <b>اللوغوس</b>: <r v=\"John.1.1\"></r>، <r v=\"John.1.14\"></r>؛ <g>τ. ζωῆς</g>، <r v=\"1John.1.1\"></r>؛ <g>τ. θεοῦ</g>، <r v=\"Rev.19.13\"></r>.</s> </s>","en":"<f><o>λόγος</o>, <g>-ου, ὁ</g> (&lt; <g>λέγω</g>),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1697\">דָּבָר</h>, also for <h n=\"H561\">אֵמֶר</h>, <h n=\"H4405\">מִלָּה</h>, etc.;]</e> </et> <s> <s n=\"I.\">Of that by which the inward thought is expressed, Lat. <l>oratio</l>, <l>sermo</l>, <l>vox</l>, <l>verbum</l>. <s n=\"1.\"><b>a word</b>, not in the grammatical sense of a mere name (<g>ἔπος</g>, <g>ὄνομα</g>, <g>ῥῆμα</g>), but a word as embodying a conception or idea: <r v=\"Matt.8.8\"></r>, <r v=\"Luke.7.7\"></r>, <r v=\"1Cor.14.9\"></r>, <r v=\"1Cor.14.19\"></r>, <r v=\"Heb.12.19\"></r>, al.</s> <s n=\"2.\"><b>a saying</b>, <b>statement</b>, <b>declaration</b>: <r v=\"Matt.19.22\"></r> (T om.), <r v=\"Mark.5.36\"></r> <r v=\"Mark.7.29\"></r>, <r v=\"Luke.1.29\"></r>, <r v=\"John.2.22\"></r> <r v=\"John.6.60\"></r>, <r v=\"Acts.7.29\"></r>, al.; c. gen. attrib., <r v=\"Acts.13.15\"></r>, <r v=\"Rom.9.9\"></r>, <r v=\"Heb.7.28\"></r>, al.; of the sayings, commands, promises, etc., of teachers, <r v=\"Matt.7.24\"></r> <r v=\"Matt.10.14\"></r>, <r v=\"Mark.8.38\"></r>, <r v=\"Luke.9.44\"></r>, <r v=\"John.14.24\"></r>, al.; <g>λ. κενοί</g>, <r v=\"Eph.5.6\"></r>; <g>ἀληθινοί</g>, <r v=\"Rev.19.9\"></r>; <g>πιστοί</g>, <r v=\"Rev.22.6\"></r>; esp. of the precepts, decrees and promises of God, <g>ὁ λ. τ. θεοῦ</g>, <b>the word of God</b>: <r v=\"Mark.7.13\"></r>, <r v=\"John.10.35\"></r>, <r v=\"Rom.13.9\"></r>, <r v=\"1Cor.14.36\"></r>, <r v=\"Phil.1.14\"></r>, al.; absol., <g>ὁ λ.</g>, <r v=\"Matt.13.21\"></r>, <r v=\"Matt.13.22\"></r>, <r v=\"Mark.16.20\"></r>, <r v=\"Luke.1.2\"></r>, <r v=\"Acts.6.4\"></r>, <r v=\"Heb.4.12\"></r>, al.</s> <s n=\"3.\"><b>speech</b>, <b>discourse</b>: <r v=\"Acts.14.12\"></r>, <r v=\"2Cor.10.10\"></r>, <r v=\"Jas.3.2\"></r>; opp. to <g>ἐπιστολή</g>, <r v=\"2Thess.2.15\"></r>; disting. from <g>σοφία</g>, <r v=\"1Cor.2.1\"></r>; <g>ἀναστροφή</g>, <r v=\"1Tim.4.12\"></r>; <g>δύναμις</g>, <r v=\"1Cor.4.19\"></r>, <r v=\"1Thess.1.5\"></r>; <g>ἔργον</g>, <r v=\"Rom.15.18\"></r>; <g>οὐδενὸς λ. τίμιον</g> (<i>not worthy of mention</i>), <r v=\"Acts.20.24\"></r>; of the faculty of speech, <r v=\"Luke.24.19\"></r>, <r v=\"2Cor.11.6\"></r>; of the style of speech, <r v=\"Matt.5.37\"></r>, <r v=\"1Cor.1.5\"></r>; of instruction, <r v=\"Col.4.3\"></r>, <r v=\"1Pet.3.1\"></r>; c. gen. pers., <r v=\"John.5.24\"></r> <r v=\"John.8.52\"></r>, <r v=\"Acts.2.41\"></r>, al.; <g>ὁ λ. ὁ ἐμός</g>, <r v=\"John.8.31\"></r>; c. gen. obj. (<g>τ.</g>) <g>ἀληθείας</g>, <r v=\"2Cor.6.7\"></r>, <r v=\"Col.1.5\"></r>, <r v=\"Jas.1.18\"></r>; <g>τ. καταλλαγῆς</g>, <r v=\"2Cor.5.19\"></r>; <g>τ. σταυροῦ</g>, <r v=\"1Cor.1.18\"></r>; of mere talk, <r v=\"1Cor.4.19\"></r>, <r v=\"1Cor.4.20\"></r>, <r v=\"Col.2.23\"></r>, <r v=\"1John.3.18\"></r>; of the talk which one occasions, hence, <b>repute</b>: <r v=\"Col.2.23\"></r>.</s> <s n=\"4.\"><b>subject-matter</b>, hence, <b>teaching</b>, <b>doctrine</b>: <r v=\"Acts.18.15\"></r>, <r v=\"2Tim.2.17\"></r>, al.; esp. of Christian doctrine: <r v=\"Matt.13.20-Matt.13.23\"></r>, <r v=\"Mark.4.14-Mark.4.20\"></r> <r v=\"Mark.8.32\"></r>, <r v=\"Luke.1.2\"></r>, <r v=\"Acts.8.4\"></r>, <r v=\"Gal.6.6\"></r>, <r v=\"1Thess.1.6\"></r>, al.; c. gen. pers., <g>τ. θεοῦ</g>, <r v=\"Luke.5.1\"></r>, <r v=\"John.17.6\"></r>, <r v=\"Acts.4.29\"></r>, <r v=\"1Cor.14.36\"></r>, <r v=\"1John.1.10\"></r>, <r v=\"Rev.6.9\"></r>, al.; <g>τ. Κυρίου</g>, <r v=\"Acts.8.25\"></r>, <r v=\"1Thess.1.8\"></r>, al.; <g>τ. Χριστοῦ</g>, <r v=\"Col.3.16\"></r>, <r v=\"Rev.3.8\"></r>; c. gen. appos., <r v=\"Acts.15.7\"></r>; c. gen. attrib., <r v=\"Heb.5.13\"></r>.</s> <s n=\"5.\"><b>a story</b>, <b>tale</b>, <b>narrative</b>: <r v=\"Matt.28.15\"></r>, <r v=\"John.21.23\"></r>, <r v=\"Acts.1.1\"></r> <r v=\"Acts.11.22\"></r>; seq. <g>περί</g>, <r v=\"Luke.5.15\"></r>.</s> <s n=\"6.\">That which is spoken of (Plat., al.; v. Kennedy, <i>Sources</i>, 124), <b>matter</b>, <b>affair</b>, <b>thing</b>: <r v=\"Matt.21.24\"></r>, <r v=\"Mark.1.45\"></r> <r v=\"Mark.11.29\"></r>, <r v=\"Luke.20.3\"></r>, <r v=\"Acts.8.21\"></r>; of a matter in dispute, as a case or suit at law, <r v=\"Acts.19.38\"></r>; pl. (<r v=\"1Macc.7.33\"></r>, al.), <r v=\"Luke.1.4\"></r>.</s> </s> <s n=\"II.\">Of the inward thought itself, Lat. <l>ratio</l>. <s n=\"1.\"><b>reason</b>, <s n=\"(a)\">of the mental faculty (Hdt., Plat., al.): <g>κατὰ λόγον</g>, <r v=\"Acts.18.14\"></r>;</s> <s n=\"(b)\"><b>a reason</b>, <b>cause</b>: <g>τίνι λόγῳ</g>, <r v=\"Acts.10.29\"></r>; <g>παρεκτὸς λόγου πορνείας</g>, <r v=\"Matt.5.32\"></r> <r v=\"Matt.19.9\"></r>, WH, mg., R, mg.</s> </s> <s n=\"2.\"><b>account</b>, <s n=\"(a)\"><b>regard</b>: <r v=\"Acts.20.24\"></r>, Rec.;</s> <s n=\"(b)\"><b>reckoning</b>: <r v=\"Phil.4.15\"></r>, <r v=\"Phil.4.16\"></r>; <g>συναίρειν</g> (q.v.) <g>λ.</g>, <r v=\"Matt.18.23\"></r> <r v=\"Matt.25.19\"></r>; in forensic sense, <r v=\"Rom.14.12\"></r>, <r v=\"Heb.13.17\"></r>, <r v=\"1Pet.4.5\"></r>; c. gen. rei, <r v=\"Luke.16.2\"></r>; seq. <g>περί</g>, <r v=\"Matt.12.36\"></r>, <r v=\"Acts.19.40\"></r>, <r v=\"1Pet.3.15\"></r>.</s> </s> <s n=\"3.\"><b>proportion</b>, <b>analogy</b>: <r v=\"Phil.2.16\"></r> (Field, <i>Notes</i>, 193 f.).</s> </s> <s n=\"III.\"><g>ὁ λ.</g>, the Divine <b>Word</b> or <b>Logos</b>: <r v=\"John.1.1\"></r>, <r v=\"John.1.14\"></r>; <g>τ. ζωῆς</g>, <r v=\"1John.1.1\"></r>; <g>τ. θεοῦ</g>, <r v=\"Rev.19.13\"></r> (v. Westc, Swete, <i>CGT</i>, in ll.; reff. in Artt., <i>Logos</i>, <i>DB</i>, <i>DCG</i>).</s> </s>"},"G3063":{"l":"λοιπός","o":55,"ar":"<f><o>λοιπός</o>، <g>-ή, -όν</g></f> <s><b>الباقي</b>، <b>البقية</b>، <s n=\"1.\">جمع، <g>οἱ λ.</g>: مع اسم، <r v=\"Matt.25.11\"></r>، <r v=\"Acts.2.37\"></r>، <r v=\"Rom.1.13\"></r>، وفي مواضع أخرى؛ مطلقًا، <r v=\"Matt.22.6\"></r>، <r v=\"Mark.16.13\"></r>، <r v=\"Luke.24.10\"></r>، وفي مواضع أخرى؛ <g>οἱ λ. οἱ</g>، <r v=\"Acts.28.9\"></r>، <r v=\"1Thess.4.13\"></r>، <r v=\"Rev.2.24\"></r>؛ <g>οἱ λ. τ. ἀνθρώπων</g>، <r v=\"Rev.9.20\"></r>؛ <g>τὰ λ.</g>، <r v=\"Mark.4.19\"></r>، <r v=\"Rev.3.2\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">المحايد المفرد (منصوب الإشارة)، ظرفيًّا، <g>τὸ λ.</g>؛ <s n=\"(a)\"><b>فيما بعد</b>، <b>من الآن فصاعدًا</b>: <r v=\"Mark.14.41\"></r>، <r v=\"1Cor.7.29\"></r>، <r v=\"Heb.10.13\"></r>؛ بدون أداة التعريف، <r v=\"Acts.27.20\"></r>، <r v=\"2Tim.4.8\"></r>؛ <g>τοῦ λ.</g> (أي <g>χρόνου</g>)، <r v=\"Gal.6.17\"></r>، <r v=\"Eph.6.10\"></r>؛</s> <s n=\"(b)\"><b>فضلاً عن ذلك</b>، <b>علاوةً على ذلك</b>، <b>أخيرًا (وأمّا الباقي)</b>: <r v=\"Phil.3.1\"></r> <r v=\"Phil.4.8\"></r>؛ بدون أداة التعريف، <r v=\"1Cor.1.16\"></r> <r v=\"1Cor.4.2\"></r>، <r v=\"1Thess.4.1\"></r>.</s> </s> </s>","en":"<f><o>λοιπός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>λείπω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3498\">יֶתֶר</h>, also for <h n=\"H7605\">שְׁאָר</h>, etc.;]</e> </et> <s><b>the remaining</b>, <b>the rest</b>, <s n=\"1.\">pl., <g>οἱ λ.</g>: c. subst., <r v=\"Matt.25.11\"></r>, <r v=\"Acts.2.37\"></r>, <r v=\"Rom.1.13\"></r>, al.; absol., <r v=\"Matt.22.6\"></r>, <r v=\"Mark.16.13\"></r>, <r v=\"Luke.24.10\"></r>, al.; <g>οἱ λ. οἱ</g> (Bl., § 47, 8), <r v=\"Acts.28.9\"></r>, <r v=\"1Thess.4.13\"></r>, <r v=\"Rev.2.24\"></r>; <g>οἱ λ. τ. ἀνθρώπων</g> (LS, s.v., ad. init.), <r v=\"Rev.9.20\"></r>; <g>τὰ λ.</g>, <r v=\"Mark.4.19\"></r>, <r v=\"Rev.3.2\"></r>, al.</s> <s n=\"2.\">Neut. sing. (acc. ref.), adverbially, <g>τὸ λ.</g>; <s n=\"(a)\"><b>for the future</b>, <b>henceforth</b>: <r v=\"Mark.14.41\"></r>, <r v=\"1Cor.7.29\"></r> (Lft., <i>Notes</i>, 232 f.), <r v=\"Heb.10.13\"></r>; anarth. (Deiss., <i>LAE</i>, 176<i>16</i>, 188<i>5</i>, <i>20</i>), <r v=\"Acts.27.20\"></r>, <r v=\"2Tim.4.8\"></r>; <g>τοῦ λ.</g> (sc. <g>χρόνου</g>; LS, s.v.; M, <i>Pr.</i>, 73; Bl., § 36, 13), <r v=\"Gal.6.17\"></r>, <r v=\"Eph.6.10\"></r>;</s> <s n=\"(b)\"><b>besides</b>, <b>moreover</b>, <b>for the rest</b>: <r v=\"Phil.3.1\"></r> <r v=\"Phil.4.8\"></r>; anarth., <r v=\"1Cor.1.16\"></r> <r v=\"1Cor.4.2\"></r>, <r v=\"1Thess.4.1\"></r> (M, <i>Th.</i>, in l; Lft., <i>Notes</i>, 51).</s> </s> </s>"},"G3076":{"l":"λυπέω","o":26,"ar":"<f><o>λυπέω</o>، <g>-ῶ</g></f> <s><b>يُكدِّر</b>، <b>يُحزن</b>، <b>يُسبِّب ألمًا</b> أو <b>حزنًا</b>: مع منصوب الشخص، <r v=\"2Cor.2.2\"></r>، <r v=\"2Cor.2.5\"></r> <r v=\"2Cor.7.8\"></r>؛ المبني للمجهول، <r v=\"Matt.14.9\"></r> <r v=\"Matt.17.23\"></r> <r v=\"Matt.18.31\"></r> <r v=\"Matt.19.22\"></r> <r v=\"Matt.26.22\"></r>، <r v=\"Mark.10.22\"></r> <r v=\"Mark.14.19\"></r>، <r v=\"John.16.20\"></r> <r v=\"John.21.17\"></r>، <r v=\"Rom.14.15\"></r>، <r v=\"2Cor.2.4\"></r>، <r v=\"1Thess.4.13\"></r>، <r v=\"1Pet.1.6\"></r>؛ <g>λ. καὶ ἀδημονεῖν</g>، <r v=\"Matt.26.37\"></r>؛ عكس <g>χαίρειν</g>، <r v=\"2Cor.6.10\"></r>؛ <g>κατὰ θεόν</g>، <r v=\"2Cor.7.9\"></r>، <r v=\"2Cor.7.11\"></r>؛ <g>τ. πνεῦμα τ. ἅγιον</g>، <r v=\"Eph.4.30\"></r> (قارن <g>συν-λνπέω</g>).†</s>","en":"<f><o>λυπέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>λύπη</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H2734\">חרה</h>, etc.;]</e> </et> <s><b>to distress</b>, <b>grieve</b>, <b>cause pain</b> or <b>grief</b>: c. acc. pers., <r v=\"2Cor.2.2\"></r>, <r v=\"2Cor.2.5\"></r> <r v=\"2Cor.7.8\"></r>; pass., <r v=\"Matt.14.9\"></r> <r v=\"Matt.17.23\"></r> <r v=\"Matt.18.31\"></r> <r v=\"Matt.19.22\"></r> <r v=\"Matt.26.22\"></r>, <r v=\"Mark.10.22\"></r> <r v=\"Mark.14.19\"></r>, <r v=\"John.16.20\"></r> <r v=\"John.21.17\"></r>, <r v=\"Rom.14.15\"></r>, <r v=\"2Cor.2.4\"></r>, <r v=\"1Thess.4.13\"></r>, <r v=\"1Pet.1.6\"></r>; <g>λ. καὶ ἀδημονεῖν</g>, <r v=\"Matt.26.37\"></r>; opp. to <g>χαίρειν</g>, <r v=\"2Cor.6.10\"></r>; <g>κατὰ θεόν</g>, <r v=\"2Cor.7.9\"></r>, <r v=\"2Cor.7.11\"></r>; <g>τ. πνεῦμα τ. ἅγιον</g>, <r v=\"Eph.4.30\"></r> (cf. <g>συν-λνπέω</g>).†</s> <sy><i>SYN.</i>: v.s. <g>θρηνέω</g>.</sy>"},"G3089":{"l":"λύω","o":42,"ar":"<f><o>λύω</o>،</f> <s n=\"1.\"><b>يحلّ</b>، <b>يفكّ الرباط</b>، <b>يُطلق</b>: عن الأشياء، <r v=\"Mark.1.7\"></r>، <r v=\"Luke.3.16\"></r>، وفي مواضع أخرى؛ عن البهائم، <r v=\"Matt.21.2\"></r>، <r v=\"Luke.13.15\"></r>، وفي مواضع أخرى؛ عن الأشخاص، <r v=\"John.11.44\"></r>، <r v=\"Acts.22.30\"></r>؛ عن الشيطان، <r v=\"Rev.20.3\"></r>، <r v=\"Rev.20.7\"></r>؛ مجازيًا، عن رباط الزواج، <r v=\"1Cor.7.27\"></r>؛ عن المريض، <r v=\"Luke.13.16\"></r>؛ عن التحرير من الخطية، <r v=\"Rev.1.5\"></r>.</s> <s n=\"2.\">يُحلِّل الكلَّ إلى أجزائه، <b>يُرخي</b>، <b>يُذيب (يَحُلّ)</b>، <b>يُفكِّك</b>، <b>يهدم</b>: <r v=\"John.2.19\"></r>، <r v=\"Acts.27.41\"></r>، <r v=\"Rev.5.2\"></r>؛ مجازيًا، <r v=\"2Pet.3.11\"></r>؛ عن الجمع (الاجتماع)، <b>يصرف</b>: <r v=\"Acts.13.43\"></r>؛ <g>τ. μεσότοιχον τ. φραγμοῦ</g>، <r v=\"Eph.2.14\"></r>؛ <g>τ. στοιχεῖα</g>، <r v=\"2Pet.3.10\"></r>؛ <g>οὐρανοί</g>، <r v=\"2Pet.3.12\"></r>؛ <g>τ. ἔργα τ. διαβόλου</g>، <r v=\"1John.3.8\"></r>؛ <g>τ. ὠδῖνας τ. θανάτου</g>، <r v=\"Acts.2.24\"></r>؛ عن الشرائع، إلخ.، <b>ينقض</b>، <b>يُبطل</b>، <b>يُلغي</b>: <g>ἐντολήν</g>، <r v=\"Matt.5.19\"></r>؛ <g>τ. νόμον</g>، <r v=\"John.7.23\"></r>؛ <g>τ. σάββατον</g>، <r v=\"John.5.18\"></r>؛ <g>τ. γραφήν</g>، <r v=\"John.10.35\"></r>. (قارن <g>ἀνα-</g>، <g>ἀπο-</g>، <g>δια-</g>، <g>ἐκ-</g>، <g>ἐπι-</g>، <g>κατα-</g>، <g>παρα-λύω</g>.)</s>","en":"<f><o>λύω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6605\">פּתח</h>, <h n=\"H5425\">נתר</h> hi., etc.;]</e> </et> <s n=\"1.\"><b>to loose</b>, <b>unbind</b>, <b>release</b>: of things, <r v=\"Mark.1.7\"></r>, <r v=\"Luke.3.16\"></r>, al.; of beasts, <r v=\"Matt.21.2\"></r>, <r v=\"Luke.13.15\"></r>, al.; of persons, <r v=\"John.11.44\"></r>, <r v=\"Acts.22.30\"></r>; of Satan, <r v=\"Rev.20.3\"></r>, <r v=\"Rev.20.7\"></r>; metaph., of the marriage tie, <r v=\"1Cor.7.27\"></r>; of one diseased, <r v=\"Luke.13.16\"></r>; of release from sin, <r v=\"Rev.1.5\"></r>, WH, R, txt. (v.s. <g>λούω</g>).</s> <s n=\"2.\">To resolve a whole into its parts, <b>loosen</b>, <b>dissolve</b>, <b>break up</b>, <b>destroy</b>: <r v=\"John.2.19\"></r>, <r v=\"Acts.27.41\"></r>, <r v=\"Rev.5.2\"></r>; metaph., <r v=\"2Pet.3.11\"></r>; of an assembly, <b>to dismiss</b>: <r v=\"Acts.13.43\"></r>; <g>τ. μεσότοιχον τ. φραγμοῦ</g>, <r v=\"Eph.2.14\"></r>; <g>τ. στοιχεῖα</g>, <r v=\"2Pet.3.10\"></r>; <g>οὐρανοί</g>, <r v=\"2Pet.3.12\"></r>; <g>τ. ἔργα τ. διαβόλου</g>, <r v=\"1John.3.8\"></r>; <g>τ. ὠδῖνας τ. θανάτου</g>, <r v=\"Acts.2.24\"></r>; of laws, etc., <b>to break</b>, <b>annul</b>, <b>cancel</b> (MM, xvi): <g>ἐντολήν</g>, <r v=\"Matt.5.19\"></r>; <g>τ. νόμον</g>, <r v=\"John.7.23\"></r>; <g>τ. σάββατον</g>, <r v=\"John.5.18\"></r>; <g>τ. γραφήν</g>, <r v=\"John.10.35\"></r>. (Cf. <g>ἀνα-</g>, <g>ἀπο-</g>, <g>δια-</g>, <g>ἐκ-</g>, <g>ἐπι-</g>, <g>κατα-</g>, <g>παρα-λύω</g>.)</s>"},"G3062":{"l":"λοιπός","o":55,"ar":"<f><o>λοιπός</o>، <g>-ή, -όν</g></f> <s><b>الباقي</b>، <b>البقية</b>، <s n=\"1.\">جمع، <g>οἱ λ.</g>: مع اسم، <r v=\"Matt.25.11\"></r>، <r v=\"Acts.2.37\"></r>، <r v=\"Rom.1.13\"></r>، وفي مواضع أخرى؛ مطلقًا، <r v=\"Matt.22.6\"></r>، <r v=\"Mark.16.13\"></r>، <r v=\"Luke.24.10\"></r>، وفي مواضع أخرى؛ <g>οἱ λ. οἱ</g>، <r v=\"Acts.28.9\"></r>، <r v=\"1Thess.4.13\"></r>، <r v=\"Rev.2.24\"></r>؛ <g>οἱ λ. τ. ἀνθρώπων</g>، <r v=\"Rev.9.20\"></r>؛ <g>τὰ λ.</g>، <r v=\"Mark.4.19\"></r>، <r v=\"Rev.3.2\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">المحايد المفرد (منصوب الإشارة)، ظرفيًّا، <g>τὸ λ.</g>؛ <s n=\"(a)\"><b>فيما بعد</b>، <b>من الآن فصاعدًا</b>: <r v=\"Mark.14.41\"></r>، <r v=\"1Cor.7.29\"></r>، <r v=\"Heb.10.13\"></r>؛ بدون أداة التعريف، <r v=\"Acts.27.20\"></r>، <r v=\"2Tim.4.8\"></r>؛ <g>τοῦ λ.</g> (أي <g>χρόνου</g>)، <r v=\"Gal.6.17\"></r>، <r v=\"Eph.6.10\"></r>؛</s> <s n=\"(b)\"><b>فضلاً عن ذلك</b>، <b>علاوةً على ذلك</b>، <b>أخيرًا (وأمّا الباقي)</b>: <r v=\"Phil.3.1\"></r> <r v=\"Phil.4.8\"></r>؛ بدون أداة التعريف، <r v=\"1Cor.1.16\"></r> <r v=\"1Cor.4.2\"></r>، <r v=\"1Thess.4.1\"></r> .</s> </s> </s>","en":"<f><o>λοιπός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>λείπω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3498\">יֶתֶר</h>, also for <h n=\"H7605\">שְׁאָר</h>, etc.;]</e> </et> <s><b>the remaining</b>, <b>the rest</b>, <s n=\"1.\">pl., <g>οἱ λ.</g>: c. subst., <r v=\"Matt.25.11\"></r>, <r v=\"Acts.2.37\"></r>, <r v=\"Rom.1.13\"></r>, al.; absol., <r v=\"Matt.22.6\"></r>, <r v=\"Mark.16.13\"></r>, <r v=\"Luke.24.10\"></r>, al.; <g>οἱ λ. οἱ</g> (Bl., § 47, 8), <r v=\"Acts.28.9\"></r>, <r v=\"1Thess.4.13\"></r>, <r v=\"Rev.2.24\"></r>; <g>οἱ λ. τ. ἀνθρώπων</g> (LS, s.v., ad. init.), <r v=\"Rev.9.20\"></r>; <g>τὰ λ.</g>, <r v=\"Mark.4.19\"></r>, <r v=\"Rev.3.2\"></r>, al.</s> <s n=\"2.\">Neut. sing. (acc. ref.), adverbially, <g>τὸ λ.</g>; <s n=\"(a)\"><b>for the future</b>, <b>henceforth</b>: <r v=\"Mark.14.41\"></r>, <r v=\"1Cor.7.29\"></r> (Lft., <i>Notes</i>, 232 f.), <r v=\"Heb.10.13\"></r>; anarth. (Deiss., <i>LAE</i>, 176<i>16</i>, 188<i>5</i>, <i>20</i>), <r v=\"Acts.27.20\"></r>, <r v=\"2Tim.4.8\"></r>; <g>τοῦ λ.</g> (sc. <g>χρόνου</g>; LS, s.v.; M, <i>Pr.</i>, 73; Bl., § 36, 13), <r v=\"Gal.6.17\"></r>, <r v=\"Eph.6.10\"></r>;</s> <s n=\"(b)\"><b>besides</b>, <b>moreover</b>, <b>for the rest</b>: <r v=\"Phil.3.1\"></r> <r v=\"Phil.4.8\"></r>; anarth., <r v=\"1Cor.1.16\"></r> <r v=\"1Cor.4.2\"></r>, <r v=\"1Thess.4.1\"></r> (M, <i>Th.</i>, in l; Lft., <i>Notes</i>, 51).</s> </s> </s>"},"G3067":{"l":"λουτρόν","o":2,"ar":"<f><o>λουτρόν</o>، <g>-οῦ, τό</g></f> <s><b>غَسْل</b>، <b>حمّام (مَغْسَل)</b>: <g>τ. ὕδατος</g>، <r v=\"Eph.5.26\"></r>؛ <g>τ. παλιγγενεσίας</g>، <r v=\"Titus.3.5\"></r> (قارن <r v=\"Eph.5.26\"></r>).†</s>","en":"<f><o>λουτρόν</o>, <g>-οῦ, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>λούω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Song.4.2\"></r> <r v=\"Song.6.5\"></r>, (<r v=\"Song.6.6\"></r>) (<h n=\"H7367\">רַחְצָה</h>), <r v=\"Sir.34.25\"></r>*;]</e> </et> <s><b>a washing</b>, <b>bath</b>: <g>τ. ὕδατος</g>, <r v=\"Eph.5.26\"></r>; <g>τ. παλιγγενεσίας</g>, <r v=\"Titus.3.5\"></r> (v. AR, <r v=\"Eph.5.26\"></r>).†</s>"},"G3008":{"l":"λειτουργέω","o":3,"ar":"<f><o>λειτουργέω</o>، <g>-ῶ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: في أثينا، <b>يتولّى الخدمات العامة على نفقته الخاصة</b>، <b>يؤدي خدمة عامة للدولة</b>، ومن ثَمَّ، بوجه عام،</s> <s n=\"2.\"><b>يخدم الدولة</b>، <b>يؤدي خدمة</b>، <b>يخدم</b>: عن الخدمة الرسمية للكهنة واللاويين (<r v=\"Exod.29.30\"></r>، <r v=\"Num.16.9\"></r>، <r v=\"Sir.4.14\"></r>، <r v=\"1Macc.10.42\"></r>، وفي مواضع أخرى)، <r v=\"Heb.10.11\"></r>؛ عن المسيحيين: مع القابل للأشخاص يليه <g>ἐν</g>، <r v=\"Rom.15.27\"></r> (قارن <r v=\"Sir.10.25\"></r>)؛ <g>τ. κυρίῳ</g>، <r v=\"Acts.13.2\"></r>.†</s>","en":"<f><o>λειτουργέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>λειτουργός</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8334\">שׁרת</h> pi., also for <h n=\"H5647\">עבד</h>, <h n=\"H6633\">צבא</h>, etc.;]</e> </et> <s n=\"1.\">in cl., at Athens, <b>to supply public offices at one's own cost</b>, <b>render public service to the State</b>, hence, generally,</s> <s n=\"2.\"><b>to serve the State</b>, <b>do a service</b>, <b>serve</b> (of service to the Gods, Diod., i, 21): of the official service of priests and Levites (<r v=\"Exod.29.30\"></r>, <r v=\"Num.16.9\"></r>, <r v=\"Sir.4.14\"></r>, <r v=\"1Macc.10.42\"></r>, al.; cf. Deiss., <i>BS</i>, 140 f.), <r v=\"Heb.10.11\"></r>; of Christians: c. dat. pers. seq. <g>ἐν</g>, <r v=\"Rom.15.27\"></r> (cf. <r v=\"Sir.10.25\"></r>); <g>τ. κυρίῳ</g>, <r v=\"Acts.13.2\"></r>.†</s> <sy><i>SYN.</i>: <g>λατρεύω</g> (q.v.), prop., <i>to serve for hire</i>, LXX (as sometimes in cl.), always of service to the deity on the part of both priests and people (<r v=\"Exod.4.3\"></r>, <r v=\"Deut.10.12\"></r>, and similarly in NT). <g>λειτουργέω</g> \"is the fulfilment of an office: it has a definite representative character, and corresponds with a function to be discharged\". It is therefore used of serving in an office or ministry: in LXX always of priests and Levites, in NT, with its cognates (<r v=\"Rom.13.6\"></r> <r v=\"Rom.15.27\"></r>, are not really exceptions), of services rendered either to God or man by apostles, prophets, teachers, and other officers of the church (cf. Tr., <i>Syn.</i>, § xxxv; <i>ICC</i> on <r v=\"Rom.1.9\"></r>; Westc., <i>He.</i>, 232 ff.).</sy>"},"G3029":{"l":"λίαν","o":12,"ar":"<f><o>λίαν</o>،</f> ظرف، <s><b>جدًّا</b>، <b>للغاية</b>: <r v=\"Matt.2.16\"></r> <r v=\"Matt.4.8\"></r> <r v=\"Matt.8.28\"></r> <r v=\"Matt.27.14\"></r>، <r v=\"Mark.1.35\"></r> <r v=\"Mark.6.51\"></r> <r v=\"Mark.9.3\"></r> <r v=\"Mark.16.2\"></r>، <r v=\"Luke.23.8\"></r>، <r v=\"2Tim.4.15\"></r>، <r v=\"2John.1.4\"></r>، <r v=\"3John.1.3\"></r> (قارن <g>ὑτερλίαν</g>).†</s>","en":"<f><o>λίαν</o>,</f> adv., <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3966\">מְאֹד</h> <r v=\"Gen.1.31\"></r> <r v=\"Gen.4.5\"></r>, <r v=\"Jer.24.3\"></r>, al.; <r v=\"Tob.9.4\"></r>, <r v=\"2Macc.11.1\"></r>, al.;]</e> </et> <s><b>very</b>, <b>exceedingly</b>: <r v=\"Matt.2.16\"></r> <r v=\"Matt.4.8\"></r> <r v=\"Matt.8.28\"></r> <r v=\"Matt.27.14\"></r>, <r v=\"Mark.1.35\"></r> <r v=\"Mark.6.51\"></r> (Rec. <g>λ. ἐκ περισσοῦ</g>) <r v=\"Mark.9.3\"></r> <r v=\"Mark.16.2\"></r>, <r v=\"Luke.23.8\"></r>, <r v=\"2Tim.4.15\"></r>, <r v=\"2John.1.4\"></r>, <r v=\"3John.1.3\"></r> (cf. <g>ὑτερλίαν</g>).†</s>"},"G3050":{"l":"λογικός","o":2,"ar":"<f>* <o>λογικός</o>، <g>-ή, -όν</g></f> <s><b>عقلي</b>، <b>عاقل</b>: <g>λατρεία</g>، <r v=\"Rom.12.1\"></r>؛ <g>τὸ λ.</g> (أي <i>الروحي</i>) <g>γάλα</g>، <r v=\"1Pet.2.2\"></r> (وتأييدًا لترجمة الترجمة المعتمدة <i>لبن الكلمة</i>).†</s>","en":"<f>* <o>λογικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>λόγος</g>, <i>reason</i>),</e> </et> <s><b>reasonable</b>, <b>rational</b>: <g>λατρεία</g>, <r v=\"Rom.12.1\"></r>; <g>τὸ λ.</g> (i.e. <i>spiritual</i>) <g>γάλα</g> (v. Hort, in l.; MM, xvi), <r v=\"1Pet.2.2\"></r> (in support of AV,<i> milk of the word</i>, v. <i>ICC</i>, in l.).†</s>"},"G3007":{"l":"λείπω","o":6,"ar":"<f><o>λείπω</o>،</f> <s n=\"1.\">متعدٍّ: <b>يترك</b>، <b>يخلّف وراءه</b>؛ المبني للمجهول: <b>يتخلّف</b>، <b>يعوزه</b>، يليه حرف الجر <g>ἐν</g>، <r v=\"Jas.1.4\"></r>؛ مع المضاف إليه للشيء، <r v=\"Jas.1.5\"></r>، <r v=\"Jas.2.15\"></r>.</s> <s n=\"2.\">لازم: <b>يزول</b>، <b>يكون ناقصًا</b>: مع القابل للشخص، <r v=\"Luke.18.22\"></r>، <r v=\"Titus.3.13\"></r>؛ <g>τὰ λείποντα</g>، <r v=\"Titus.1.5\"></r> (قارن <g>ἀπο-</g>، <g>δια-</g>، <g>ἐκ-</g>، <g>ἐπι-</g>، <g>κατα-</g>، <g>ἐν-κατα-</g>، <g>περι-</g>، <g>ὑπο-λείπω</g>).†</s>","en":"<f><o>λείπω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.4.11\"></r>, <r v=\"Prov.19.1\"></r> (<r v=\"Prov.19.4\"></r>) (<h n=\"H6504\">פּרד</h>), al.;]</e> </et> <s n=\"1.\">trans., <b>to leave</b>, <b>leave behind</b>; pass., <b>to be left behind</b>, <b>to lack</b> seq. prep. (as more usual in cl.), <g>ἐν</g>, <r v=\"Jas.1.4\"></r>; c. gen. rei, <r v=\"Jas.1.5\"></r> <r v=\"Jas.2.15\"></r>.</s> <s n=\"2.\">Intrans., <b>to be gone</b>, <b>to be wanting</b>: c. dat. pers., <r v=\"Luke.18.22\"></r>, <r v=\"Titus.3.13\"></r>; <g>τὰ λείποντα</g>, <r v=\"Titus.1.5\"></r> (cf. <g>ἀπο-</g>, <g>δια-</g>, <g>ἐκ-</g>, <g>ἐπι-</g>, <g>κατα-</g>, <g>ἐν-κατα-</g>, <g>περι-</g>, <g>ὑπο-λείπω</g>).†</s>"},"G3064":{"l":"λοιπός","o":55,"ar":"<f><o>λοιπός</o>، <g>-ή, -όν</g></f> <s><b>الباقي</b>، <b>البقية</b>، <s n=\"1.\">في الجمع، <g>οἱ λ.</g>: مع اسم، <r v=\"Matt.25.11\"></r>، <r v=\"Acts.2.37\"></r>، <r v=\"Rom.1.13\"></r>، وفي مواضع أخرى؛ مطلقًا، <r v=\"Matt.22.6\"></r>، <r v=\"Mark.16.13\"></r>، <r v=\"Luke.24.10\"></r>، وفي مواضع أخرى؛ <g>οἱ λ. οἱ</g>، <r v=\"Acts.28.9\"></r>، <r v=\"1Thess.4.13\"></r>، <r v=\"Rev.2.24\"></r>؛ <g>οἱ λ. τ. ἀνθρώπων</g>، <r v=\"Rev.9.20\"></r>؛ <g>τὰ λ.</g>، <r v=\"Mark.4.19\"></r>، <r v=\"Rev.3.2\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">المحايد المفرد (منصوبًا على الإشارة)، ظرفًا، <g>τὸ λ.</g>؛ <s n=\"(a)\"><b>فيما بعد</b>، <b>من الآن فصاعدًا</b>: <r v=\"Mark.14.41\"></r>، <r v=\"1Cor.7.29\"></r>، <r v=\"Heb.10.13\"></r>؛ بدون أداة التعريف، <r v=\"Acts.27.20\"></r>، <r v=\"2Tim.4.8\"></r>؛ <g>τοῦ λ.</g> (والمقدَّر <g>χρόνου</g>)، <r v=\"Gal.6.17\"></r>، <r v=\"Eph.6.10\"></r>؛</s> <s n=\"(b)\"><b>فضلاً عن ذلك</b>، <b>وأيضًا</b>، <b>وأما الباقي (أخيرًا)</b>: <r v=\"Phil.3.1\"></r> <r v=\"Phil.4.8\"></r>؛ بدون أداة التعريف، <r v=\"1Cor.1.16\"></r> <r v=\"1Cor.4.2\"></r>، <r v=\"1Thess.4.1\"></r>.</s> </s> </s>","en":"<f><o>λοιπός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>λείπω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3498\">יֶתֶר</h>, also for <h n=\"H7605\">שְׁאָר</h>, etc.;]</e> </et> <s><b>the remaining</b>, <b>the rest</b>, <s n=\"1.\">pl., <g>οἱ λ.</g>: c. subst., <r v=\"Matt.25.11\"></r>, <r v=\"Acts.2.37\"></r>, <r v=\"Rom.1.13\"></r>, al.; absol., <r v=\"Matt.22.6\"></r>, <r v=\"Mark.16.13\"></r>, <r v=\"Luke.24.10\"></r>, al.; <g>οἱ λ. οἱ</g> (Bl., § 47, 8), <r v=\"Acts.28.9\"></r>, <r v=\"1Thess.4.13\"></r>, <r v=\"Rev.2.24\"></r>; <g>οἱ λ. τ. ἀνθρώπων</g> (LS, s.v., ad. init.), <r v=\"Rev.9.20\"></r>; <g>τὰ λ.</g>, <r v=\"Mark.4.19\"></r>, <r v=\"Rev.3.2\"></r>, al.</s> <s n=\"2.\">Neut. sing. (acc. ref.), adverbially, <g>τὸ λ.</g>; <s n=\"(a)\"><b>for the future</b>, <b>henceforth</b>: <r v=\"Mark.14.41\"></r>, <r v=\"1Cor.7.29\"></r> (Lft., <i>Notes</i>, 232 f.), <r v=\"Heb.10.13\"></r>; anarth. (Deiss., <i>LAE</i>, 176<i>16</i>, 188<i>5</i>, <i>20</i>), <r v=\"Acts.27.20\"></r>, <r v=\"2Tim.4.8\"></r>; <g>τοῦ λ.</g> (sc. <g>χρόνου</g>; LS, s.v.; M, <i>Pr.</i>, 73; Bl., § 36, 13), <r v=\"Gal.6.17\"></r>, <r v=\"Eph.6.10\"></r>;</s> <s n=\"(b)\"><b>besides</b>, <b>moreover</b>, <b>for the rest</b>: <r v=\"Phil.3.1\"></r> <r v=\"Phil.4.8\"></r>; anarth., <r v=\"1Cor.1.16\"></r> <r v=\"1Cor.4.2\"></r>, <r v=\"1Thess.4.1\"></r> (M, <i>Th.</i>, in l; Lft., <i>Notes</i>, 51).</s> </s> </s>"},"G3000":{"l":"λατρεύω","o":21,"ar":"<f><o>λατρεύω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>عمل بأجرة</b>.</s> <s n=\"2.\"><b>خدم</b>؛ وفي الكلاسيكية أيضًا عن الخدمة الإلهية: <b>خدم</b>، <b>عبد</b>، وهكذا دائمًا في العهد الجديد: مع قابل الشخص، <g>τ. θεῷ</g>: <r v=\"Matt.4.10\"></r>، <r v=\"Luke.4.8\"></r><i>(السبعينية)</i>، <r v=\"Acts.7.7\"></r>، <r v=\"Acts.24.14\"></r>، <r v=\"Acts.27.23\"></r>، <r v=\"Heb.9.14\"></r>، <r v=\"Rev.7.15\"></r>، <r v=\"Rev.22.3\"></r>؛ عن عبادة الأوثان (قارن <r v=\"Exod.20.5\"></r>، <r v=\"Ezek.20.32\"></r>): <r v=\"Acts.7.42\"></r>، <r v=\"Rom.1.25\"></r>؛ <g>τ. θεῷ ἐν τ. πνεύματί μου</g>: <r v=\"Rom.1.9\"></r>؛ وكذلك <g>ἐν καθαρᾷ συνειδήσει</g>: <r v=\"2Tim.1.3\"></r>؛ <g>μετ’ εὐλαβείας κ. δέους</g>: <r v=\"Heb.12.28\"></r>؛ <g>ἐν ὁσιότητι κ. δικαιοσύνῃ</g>: <r v=\"Luke.1.74\"></r>؛ (بدون <g>θεῷ</g>) <g>νηστείαις κ. δεήσεσι</g>: <r v=\"Luke.2.37\"></r>؛ <g>πνεύματι θεοῦ</g>: <r v=\"Phil.3.3\"></r>؛ مطلقًا: <r v=\"Acts.26.7\"></r>؛ <g>ὁ λατρεύων</g>: <b>العابد</b>: <r v=\"Heb.9.9\"></r>، <r v=\"Heb.10.2\"></r>؛ عن الخدمة الكهنوتية، مع قابل الشيء: <r v=\"Heb.8.5\"></r>، <r v=\"Heb.13.10\"></r>.†</s>","en":"<f><o>λατρεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>λάτρις</g>, <i>a hired servant</i>),</e> <e t=\"septuagint\">[in LXX (always, as <g>λατρεία</g>, of the service of God or of heathen divinities) chiefly for <h n=\"H5647\">עבד</h>, <r v=\"Exod.3.12\"></r>, al.; in Da LXX TH (<r v=\"Dan.3.12\"></r>, al.) for <h n=\"H6399\">פְּלַח</h>;]</e> </et> <s n=\"1.\"><b>to work for hire</b>.</s> <s n=\"2.\"><b>to serve</b>; in cl., also of divine service, <b>to serve</b>, <b>worship</b>, and so always in NT: c. dat. pers., <g>τ. θεῷ</g>, <r v=\"Matt.4.10\"></r>, <r v=\"Luke.4.8\"></r><i>(LXX)</i>, <r v=\"Acts.7.7\"></r> <r v=\"Acts.24.14\"></r> <r v=\"Acts.27.23\"></r>, <r v=\"Heb.9.14\"></r>, <r v=\"Rev.7.15\"></r> <r v=\"Rev.22.3\"></r>; of idol worship (cf. <r v=\"Exod.20.5\"></r>, <r v=\"Ezek.20.32\"></r>), <r v=\"Acts.7.42\"></r>, <r v=\"Rom.1.25\"></r>; <g>τ. θεῷ ἐν τ. πνεύματί μου</g>, <r v=\"Rom.1.9\"></r>; id. <g>ἐν καθαρᾷ συνειδήσει</g>, <r v=\"2Tim.1.3\"></r>; <g>μετ’ εὐλαβείας κ. δέους</g>, <r v=\"Heb.12.28\"></r>; <g>ἐν ὁσιότητι κ. δικαιοσύνῃ</g>, <r v=\"Luke.1.74\"></r>; (without <g>θεῷ</g>) <g>νηστείαις κ. δεήσεσι</g>, <r v=\"Luke.2.37\"></r>; <g>πνεύματι θεοῦ</g>, <r v=\"Phil.3.3\"></r>; absol., <r v=\"Acts.26.7\"></r>; <g>ὁ λατρεύων</g>, <b>the worshipper</b>, <r v=\"Heb.9.9\"></r> <r v=\"Heb.10.2\"></r>; of ministerial service, c. dat. rei, <r v=\"Heb.8.5\"></r> <r v=\"Heb.13.10\"></r>.†</s> <sy><i>SYN.</i>: <g>λειτουργέω</g>, q.v.</sy>"},"G3053":{"l":"λογισμός","o":2,"ar":"<f><o>λογισμός</o>، <g>-οῦ, ὁ</g></f> <s><b>تفكير</b>، <b>ظنّ (فكر)</b>: <r v=\"Rom.2.15\"></r>، <r v=\"2Cor.10.5\"></r>.†</s>","en":"<f><o>λογισμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>λογίζομαι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.33.10\"></r>, <r v=\"Ps.33.11\"></r>, <r v=\"Prov.19.21\"></r>, <r v=\"Isa.66.18\"></r>, al. (<h n=\"H4284\">מַחֲשֶׁבֶת</h>);]</e> </et> <s><b>a reasoning</b>, <b>thought</b>: <r v=\"Rom.2.15\"></r>, <r v=\"2Cor.10.5\"></r>.†</s>"},"G3044":{"l":"Λίνος","o":1,"ar":"<f><o>Λίνος</o>، <g>ου, ὁ</g>،</f> <s><b>لينُس</b>: <r v=\"2Tim.4.21\"></r>.†</s>","en":"<f><o>Λίνος</o> (Rec. <g>Λῖνος</g>), <g>ου, ὁ</g>,</f> <s><b>Linus</b>: <r v=\"2Tim.4.21\"></r>.†</s>"},"G3077":{"l":"λύπη","o":16,"ar":"<f><o>λύπη</o>، <g>-ης, ἡ</g>،</f> <s><b>ألم</b> في الجسد أو النفس، <b>غمّ</b>، <b>حزن</b>: <r v=\"John.16.6\"></r>، <r v=\"2Cor.2.7\"></r>؛ عكس <g>χαρά</g>، <r v=\"John.16.20\"></r>، <r v=\"Heb.12.11\"></r>؛ <g>ἀπὸ τῆς λ.</g>، <r v=\"Luke.22.45\"></r>؛ <g>ἐκ λ.</g>، <r v=\"2Cor.9.7\"></r>؛ <g>ἡ κατὰ θεὸν λ.</g>، عكس <g>ἡ τ. κόσμου λ.</g>، <r v=\"2Cor.7.10\"></r>؛ <g>λ. μοί ἐστιν</g>، <r v=\"Rom.9.2\"></r>؛ <g>λ. ἔχω</g>، <r v=\"John.16.21\"></r>، <r v=\"John.16.22\"></r>؛ وكذلك يليه <g>ἀπό</g>، <r v=\"2Cor.2.3\"></r>؛ <g>λ. ἐπὶ λ. ἔχω</g>، <r v=\"Phil.2.27\"></r>؛ <g>ἐν λ. ἐλθεῖν</g>، <r v=\"2Cor.2.1\"></r> (أن يأتي حزينًا ويسبّب الحزن)؛ في الجمع (قارن <r v=\"Gen.3.16\"></r>، <r v=\"Prov.15.13\"></r>، وفي مواضع أخرى)، <r v=\"1Pet.2.19\"></r>.†</s>","en":"<f><o>λύπη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6089\">עֶצֶב</h> and cogn. forms, etc.;]</e> </et> <s><b>pain</b> of body or mind, <b>grief</b>, <b>sorrow</b>: <r v=\"John.16.6\"></r>, <r v=\"2Cor.2.7\"></r>; opp. to <g>χαρά</g>, <r v=\"John.16.20\"></r>, <r v=\"Heb.12.11\"></r>; <g>ἀπὸ τῆς λ.</g>, <r v=\"Luke.22.45\"></r>; <g>ἐκ λ.</g>, <r v=\"2Cor.9.7\"></r>; <g>ἡ κατὰ θεὸν λ.</g>, opp. to <g>ἡ τ. κόσμου λ.</g>, <r v=\"2Cor.7.10\"></r>; <g>λ. μοί ἐστιν</g>, <r v=\"Rom.9.2\"></r>; <g>λ. ἔχω</g>, <r v=\"John.16.21\"></r>, <r v=\"John.16.22\"></r>; id. seq. <g>ἀπό</g>, <r v=\"2Cor.2.3\"></r>; <g>λ. ἐπὶ λ. ἔχω</g>, <r v=\"Phil.2.27\"></r>; <g>ἐν λ. ἐλθεῖν</g>, <r v=\"2Cor.2.1\"></r> (to come sad and cause sadness); pl. (cf. <r v=\"Gen.3.16\"></r>, <r v=\"Prov.15.13\"></r>, al.), <r v=\"1Pet.2.19\"></r>.†</s>"},"G3009":{"l":"λειτουργία","o":6,"ar":"<f><o>λειτουργία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية (خاصةً في أثينا): <b>القيام بوظيفة عامة على نفقة المرء الخاصة</b>، ومن ثمّ،</s> <s n=\"2.\"><b>خدمة</b>؛ وفي السبعينية (وإن جاءت فيها أيضًا عن الخدمة الدنيوية، <r v=\"1Kgs.1.4\"></r>، وفي مواضع أخرى) عن الخدمة أو الشعائر الدينية؛ وهكذا في العهد الجديد: عن خدمات الكهنوت، <r v=\"Luke.1.23\"></r>، <r v=\"Heb.8.6\"></r>، <r v=\"Heb.9.21\"></r>؛ مجازيًا، <g>θυσία καὶ λ. τῆς πίστεως ὑμῶν</g>، <r v=\"Phil.2.17\"></r>؛ عن الإحسان المسيحي، <r v=\"2Cor.9.12\"></r>، <r v=\"Phil.2.30\"></r>.†</s>","en":"<f><o>λειτουργία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λειτουργέω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5656\">עֲבֹדָה</h>, <r v=\"Num.4.24\"></r>, <r v=\"1Chr.9.13\"></r>, al.;]</e> </et> <s n=\"1.\">in cl. (chiefly of Athens), <b>the discharge of a public office at one's own expense</b> (v. LS, s.v.), hence,</s> <s n=\"2.\"><b>a service</b>, <b>ministry</b>; in <g>π.</g> (Deiss., <i>BS</i>, 140 f.) and in LXX (though here also of secular service, <r v=\"1Kgs.1.4\"></r>, al.), of religious service or ministration; and so in NT: of priestly ministrations, <r v=\"Luke.1.23\"></r>, <r v=\"Heb.8.6\"></r> <r v=\"Heb.9.21\"></r>; fig., <g>θυσία καὶ λ. τῆς πίστεως ὑμῶν</g>, <r v=\"Phil.2.17\"></r>; of Christian beneficence, <r v=\"2Cor.9.12\"></r>, <r v=\"Phil.2.30\"></r>.†</s>"},"G3028":{"l":"λῆμψις","o":1,"ar":"<f><o>λῆμψις</o>، <g>-εως, ἡ</g></f> <s><b>أخذ، قبول</b>: <g>δόσις καὶ λ.</g>، <r v=\"Phil.4.15\"></r>.†</s>","en":"<f><o>λῆμψις</o> (Rec. <g>λῆψις</g>, so in cl.), <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λαμβάνω</g>),</e> <e t=\"septuagint\">[in LXX (<g>λῆψ-</g>): <r v=\"Prov.15.29\"></r> (<r v=\"Prov.16.8\"></r>); <g>λ. δώρων</g>, <r v=\"Prov.15.27\"></r> (<h n=\"H4979\">מַתָּנָה</h>); <g>λ. καὶ δόσις</g>, <r v=\"Sir.41.19\"></r> <r v=\"Sir.42.7\"></r>*;]</e> </et> <s><b>receiving</b>: <g>δόσις καὶ λ.</g>, <r v=\"Phil.4.15\"></r>.†</s>"},"G3037":{"l":"λίθος","o":59,"ar":"<f><o>λίθος</o>، <g>-ου, ὁ</g></f> <s><b>حجر</b>: <r v=\"Matt.4.6\"></r>، وفي مواضع أخرى؛ الجمع، <r v=\"Matt.3.9\"></r>، وفي مواضع أخرى؛ على باب القبر، <r v=\"Matt.27.60\"></r>، <r v=\"Matt.27.66\"></r> <r v=\"Matt.28.2\"></r>، <r v=\"Mark.15.46\"></r> <r v=\"Mark.16.3\"></r>، <r v=\"Mark.16.4\"></r>، <r v=\"Luke.24.2\"></r>، <r v=\"John.11.38\"></r>، <r v=\"John.11.39\"></r>، <r v=\"John.11.41\"></r> <r v=\"John.20.1\"></r>؛ <g>λ. μυλικός</g>، <r v=\"Luke.17.2\"></r>، قارن <r v=\"Rev.18.21\"></r>؛ عن حجارة البناء، <r v=\"Matt.21.42\"></r>، [<r v=\"Matt.21.44\"></r>] <r v=\"Matt.24.2\"></r>، <r v=\"Mark.12.10\"></r> <r v=\"Mark.13.1\"></r>، <r v=\"Mark.13.2\"></r>، <r v=\"Luke.19.44\"></r> <r v=\"Luke.20.17\"></r>، <r v=\"Luke.20.18\"></r> <r v=\"Luke.21.5\"></r>، <r v=\"Luke.21.6\"></r> <r v=\"Acts.4.11\"></r>، <r v=\"1Pet.2.7\"></r>؛ مجازيًا، عن المسيح، <g>λ. ἀκρογωναῖος</g>، <g>ἐκλεκτός</g>، <g>ἔντιμος</g>، <r v=\"1Pet.2.6\"></r>؛ <g>λ. ζῶν</g>، <r v=\"1Pet.2.4\"></r>؛ <g>προσκόμματος</g>، <r v=\"1Pet.2.8\"></r>، <r v=\"Rom.9.33\"></r>؛ عن المسيحيين، <g>λ. ζῶντες</g>، <r v=\"1Pet.2.5\"></r>؛ عن الحجارة الكريمة، <g>λ. τίμιος</g>، <r v=\"Rev.17.4\"></r> <r v=\"Rev.18.12\"></r>، <r v=\"Rev.18.16\"></r> <r v=\"Rev.21.11\"></r>، <r v=\"Rev.21.19\"></r>؛ <g>ἴασπις</g>، <r v=\"Rev.4.3\"></r>؛ <g>ἐνδεδυμένοι λ. καθαρόν</g>، <r v=\"Rev.15.6\"></r>؛ مجازيًا، <g>λ. τίμιοι</g>، <r v=\"1Cor.3.12\"></r>؛ عن لوحَي الشريعة، <r v=\"2Cor.3.7\"></r>؛ عن الأوثان، <r v=\"Acts.17.29\"></r>.</s>","en":"<f><o>λίθος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(and, in Att., of precious stones, <g>ἡ.</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H68\">אֶבֶן</h>, <r v=\"Gen.11.3\"></r>, al.; <g>λ. τίμιος</g>, for <h n=\"H6337\">פָּז</h>, <r v=\"Ps.19.10\"></r> <r v=\"Ps.21.3\"></r>, <r v=\"Prov.8.19\"></r>, al.;]</e> </et> <s><b>a stone</b>: <r v=\"Matt.4.6\"></r>, al.; pl., <r v=\"Matt.3.9\"></r>, al.; at the entrance of a tomb, <r v=\"Matt.27.60\"></r>, <r v=\"Matt.27.66\"></r> <r v=\"Matt.28.2\"></r>, <r v=\"Mark.15.46\"></r> <r v=\"Mark.16.3\"></r>, <r v=\"Mark.16.4\"></r>, <r v=\"Luke.24.2\"></r>, <r v=\"John.11.38\"></r>, <r v=\"John.11.39\"></r>, <r v=\"John.11.41\"></r> <r v=\"John.20.1\"></r>; <g>λ. μυλικός</g>, <r v=\"Luke.17.2\"></r>, cf. <r v=\"Rev.18.21\"></r>; of building stones, <r v=\"Matt.21.42\"></r>, [<r v=\"Matt.21.44\"></r>] <r v=\"Matt.24.2\"></r>, <r v=\"Mark.12.10\"></r> <r v=\"Mark.13.1\"></r>, <r v=\"Mark.13.2\"></r>, <r v=\"Luke.19.44\"></r> <r v=\"Luke.20.17\"></r>, <r v=\"Luke.20.18\"></r> <r v=\"Luke.21.5\"></r>, <r v=\"Luke.21.6\"></r> <r v=\"Acts.4.11\"></r>, <r v=\"1Pet.2.7\"></r>; metaph., of Christ, <g>λ. ἀκρογωναῖος</g>, <g>ἐκλεκτός</g>, <g>ἔντιμος</g>, <r v=\"1Pet.2.6\"></r><i>(LXX)</i>; <g>λ. ζῶν</g>, <r v=\"1Pet.2.4\"></r>; <g>προσκόμματος</g>, <r v=\"1Pet.2.8\"></r>, <r v=\"Rom.9.33\"></r>; of Christians, <g>λ. ζῶντες</g>, <r v=\"1Pet.2.5\"></r>; of precious stones, <g>λ. τίμιος</g>, <r v=\"Rev.17.4\"></r> <r v=\"Rev.18.12\"></r>, <r v=\"Rev.18.16\"></r> <r v=\"Rev.21.11\"></r>, <r v=\"Rev.21.19\"></r>; <g>ἴασπις</g>, <r v=\"Rev.4.3\"></r>; <g>ἐνδεδυμένοι λ. καθαρόν</g>, <r v=\"Rev.15.6\"></r> (<g>λίνον</g>, Rec., R, mg., v. Swete, in l.); metaph., <g>λ. τίμιοι</g>, <r v=\"1Cor.3.12\"></r>; of the tables of the law, <r v=\"2Cor.3.7\"></r>; of idols, <r v=\"Acts.17.29\"></r>.</s>"},"G3035":{"l":"λίθινος","o":3,"ar":"<f><o>λίθινος</o>، <g>-η, -ον</g></f> <s><b>حجري، من حجر</b>: <r v=\"John.2.6\"></r>، <r v=\"2Cor.3.3\"></r>، <r v=\"Rev.9.20\"></r>.†</s>","en":"<f><o>λίθινος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(<g>λίθος</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H68\">אֶבֶן</h>;]</e> </et> <s><b>of stone</b>: <r v=\"John.2.6\"></r>, <r v=\"2Cor.3.3\"></r>, <r v=\"Rev.9.20\"></r>.†</s>"},"G3059":{"l":"λοιδορία","o":3,"ar":"<f><o>λοιδορία</o>، <g>-ας, ἡ</g></f> <s><b>شتيمة</b>، <b>سبّ، تعيير</b>: <r v=\"1Tim.5.14\"></r>، <r v=\"1Pet.3.9\"></r>.†</s>","en":"<f><o>λοιδορία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λοιδορέω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7379\">רִיב</h>, <h n=\"H4808\">מְרִיבָה</h>;]</e> </et> <s><b>abuse</b>, <b>railing</b>: <r v=\"1Tim.5.14\"></r>, <r v=\"1Pet.3.9\"></r>.†</s>"},"G3055":{"l":"λογομαχία","o":1,"ar":"<f>*† <o>λογομαχία</o>، <g>-ας, ἡ</g></f> <s><b>مماحكة الكلام، مماحكات لفظية</b>: الجمع، <r v=\"1Tim.6.4\"></r>.†</s>","en":"<f>*† <o>λογομαχία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λογομαχέω</g>),</e> </et> <s><b>a strife of words</b>: pl., <r v=\"1Tim.6.4\"></r>.†</s>"},"G3066":{"l":"λούκιος","o":2,"ar":"<f><o>λούκιος</o>، <g>-ου, ὁ</g> (اللاتينية <l>Lucius</l>)،</f> <s><b>لوكيوس</b>: <r v=\"Acts.13.1\"></r>، <r v=\"Rom.16.21\"></r>.†</s>","en":"<f><o>λούκιος</o>, <g>-ου, ὁ</g> (Lat. <l>Lucius</l>),</f> <s><b>Lucius</b>: <r v=\"Acts.13.1\"></r>, <r v=\"Rom.16.21\"></r>.†</s>"},"G3049":{"l":"λογίζομαι","o":40,"ar":"<f><o>λογίζομαι</o></f> <s n=\"1.\">بالمعنى الحرفي، عن الحساب العددي: <b>يَعُدّ</b>، <b>يحسب</b>: مع المنصوب يليه <g>μετά</g>، <r v=\"Mark.15.23\"></r><i>(السبعينية)</i>، <r v=\"Luke.22.37\"></r>.</s> <s n=\"2.\">مجازيًا، بغير إشارة إلى الأعداد، بحساب الصفات أو الأسباب؛ <s n=\"(a)\"><b>يحسب</b>، <b>يأخذ في الحسبان</b>: مع منصوب الشيء، <r v=\"1Cor.13.5\"></r>؛ والاستعمال نفسه يليه قابل الشخص، <r v=\"Rom.4.3\"></r><i>(السبعينية)</i>، <r v=\"Rom.4.4\"></r>، <r v=\"Rom.4.6\"></r>، <r v=\"Rom.4.8\"></r><i>(السبعينية)</i>، <r v=\"2Cor.5.19\"></r>، <r v=\"2Tim.4.16\"></r>؛ يليه <g>εἰς</g> («حُسب له...»؛ قارن العبرية <h n=\"H2803\">נֶחֱשׁב לְ</h>)، <r v=\"Acts.19.27\"></r>، <r v=\"Rom.2.26\"></r> <r v=\"Rom.4.3\"></r>، <r v=\"Rom.4.5\"></r>، <r v=\"Rom.4.9-Rom.4.11\"></r>، <r v=\"Rom.4.22-Rom.4.24\"></r> <r v=\"Rom.9.8\"></r>، <r v=\"Gal.3.6\"></r><i>(السبعينية)</i>، <r v=\"Jas.2.23\"></r><i>(السبعينية)</i>؛</s> <s n=\"(b)\"><b>يتأمل</b>، <b>يفكر في، يزن الأمر</b>: مع منصوب الشيء، <r v=\"Phil.4.8\"></r>؛ يليه <g>ὅτι</g>، <r v=\"John.11.50\"></r>، <r v=\"Heb.11.10\"></r>؛ <g>τοῦτο</g>، <g>ὅτι</g>، <r v=\"2Cor.10.11\"></r>؛ مع منصوب الشخص ومع المصدر، <r v=\"Rom.6.11\"></r>؛ يليه <g>ὡς</g>، <r v=\"Rom.8.36\"></r><i>(السبعينية)</i>؛</s> <s n=\"(c)\"><b>يظن</b>، <b>يحكم</b>، <b>يعتبر</b>: <r v=\"1Cor.13.11\"></r>؛ <g>ὡς</g>، <r v=\"1Pet.5.12\"></r>؛ <g>οὕτως</g>، <r v=\"1Cor.4.1\"></r>؛ مع منصوب الشيء، <r v=\"2Cor.3.5\"></r>؛ والاستعمال نفسه يليه <g>εἰς</g>، <r v=\"2Cor.12.6\"></r>؛ <g>ὅτι</g>، <r v=\"Rom.8.18\"></r>؛ <g>τοῦτο</g>، <g>ὅτι</g>، <r v=\"Rom.2.3\"></r>، <r v=\"2Cor.10.7\"></r>؛ مع المصدر، <r v=\"2Cor.11.5\"></r>؛ منصوب ومصدر، <r v=\"Rom.3.28\"></r> <r v=\"Rom.14.14\"></r>، <r v=\"Phil.3.13\"></r>؛ مع منصوب الشخص يليه <g>ὡς</g>، <r v=\"2Cor.10.2\"></r>؛</s> <s n=\"(d)\"><b>ينوي</b>، <b>يعزم</b>: مع المصدر، <r v=\"2Cor.10.2\"></r> (قارن <g>ἀνα-</g>، <g>δια-</g>، <g>παρα-</g>، <g>συλ-λογίζομαι</g>).†</s> </s>","en":"<f><o>λογίζομαι</o></f> <et> <e t=\"derivation\">(&lt; <g>λόγος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2803\">חשׁב</h>;]</e> </et> <s n=\"1.\">prop., of numerical calculation, <b>to count</b>, <b>reckon</b>: c. acc. seq. <g>μετά</g>, <r v=\"Mark.15.23\"></r><i>(LXX)</i> (Rec., R, mg.), <r v=\"Luke.22.37\"></r>.</s> <s n=\"2.\">Metaph., without reference to numbers, by a reckoning of characteristics or reasons; <s n=\"(a)\"><b>to reckon</b>, <b>take into account</b>: c. acc. rei, <r v=\"1Cor.13.5\"></r>; id. seq. dat. pers., <r v=\"Rom.4.3\"></r><i>(LXX)</i>, <r v=\"Rom.4.4\"></r>, <r v=\"Rom.4.6\"></r>, <r v=\"Rom.4.8\"></r><i>(LXX)</i>, <r v=\"2Cor.5.19\"></r>, <r v=\"2Tim.4.16\"></r>; seq. <g>εἰς</g> (cf. Heb. <h n=\"H2803\">נֶחֱשׁב לְ</h>; Bl., § 33, 3), <r v=\"Acts.19.27\"></r>, <r v=\"Rom.2.26\"></r> <r v=\"Rom.4.3\"></r>, <r v=\"Rom.4.5\"></r>, <r v=\"Rom.4.9-Rom.4.11\"></r>, <r v=\"Rom.4.22-Rom.4.24\"></r> <r v=\"Rom.9.8\"></r>, <r v=\"Gal.3.6\"></r><i>(LXX)</i>, <r v=\"Jas.2.23\"></r><i>(LXX)</i>;</s> <s n=\"(b)\"><b>to consider</b>, <b>calculate</b>: c. acc. rei, <r v=\"Phil.4.8\"></r>; seq. <g>ὅτι</g>, <r v=\"John.11.50\"></r>, <r v=\"Heb.11.10\"></r>; <g>τοῦτο</g>, <g>ὅτι</g>, <r v=\"2Cor.10.11\"></r>; c. acc. pers., c. inf., <r v=\"Rom.6.11\"></r>; seq. <g>ὡς</g>, <r v=\"Rom.8.36\"></r><i>(LXX)</i>;</s> <s n=\"(c)\"><b>to suppose</b>, <b>judge</b>, <b>deem</b>: <r v=\"1Cor.13.11\"></r>; <g>ὡς</g>, <r v=\"1Pet.5.12\"></r>; <g>οὕτως</g>, <r v=\"1Cor.4.1\"></r>; c. acc. rei, <r v=\"2Cor.3.5\"></r>; id. seq. <g>εἰς</g>, <r v=\"2Cor.12.6\"></r>; <g>ὅτι</g>, <r v=\"Rom.8.18\"></r>; <g>τοῦτο</g>, <g>ὅτι</g>, <r v=\"Rom.2.3\"></r>, <r v=\"2Cor.10.7\"></r>; c. inf., <r v=\"2Cor.11.5\"></r>; acc. et inf., <r v=\"Rom.3.28\"></r> <r v=\"Rom.14.14\"></r>, <r v=\"Phil.3.13\"></r>; c. acc. pers. seq. <g>ὡς</g>, <r v=\"2Cor.10.2\"></r>;</s> <s n=\"(d)\"><b>to purpose</b>, <b>decide</b>: c. inf. (Eur., <i>Or.</i>, 555), <r v=\"2Cor.10.2\"></r> (cf. <g>ἀνα-</g>, <g>δια-</g>, <g>παρα-</g>, <g>συλ-λογίζομαι</g>).†</s> </s>"},"G3027":{"l":"λῃστής","o":15,"ar":"<f><o>λῃστής</o>، <g>-οῦ, ὁ</g></f> <s><b>لصّ</b>، <b>قاطع طريق</b>: <r v=\"Matt.21.13\"></r><i>(السبعينية)</i> <r v=\"Matt.26.55\"></r> <r v=\"Matt.27.38\"></r>، <r v=\"Matt.27.44\"></r>، <r v=\"Mark.11.17\"></r> <r v=\"Mark.14.48\"></r> <r v=\"Mark.15.27\"></r>، <r v=\"Luke.10.30\"></r>، <r v=\"Luke.10.36\"></r> <r v=\"Luke.19.46\"></r> <r v=\"Luke.22.52\"></r>، <r v=\"John.10.1\"></r>، <r v=\"John.10.8\"></r> <r v=\"John.18.40\"></r>، <r v=\"2Cor.11.26\"></r>.†</s>","en":"<f><o>λῃστής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; Ep. <g>ληίς</g> = <g>λεία</g>, <i>booty</i>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H1416\">גְּדוּד</h>, etc.;]</e> </et> <s><b>a robber</b>, <b>brigand</b>: <r v=\"Matt.21.13\"></r><i>(LXX)</i> <r v=\"Matt.26.55\"></r> <r v=\"Matt.27.38\"></r>, <r v=\"Matt.27.44\"></r>, <r v=\"Mark.11.17\"></r> <r v=\"Mark.14.48\"></r> <r v=\"Mark.15.27\"></r>, <r v=\"Luke.10.30\"></r>, <r v=\"Luke.10.36\"></r> <r v=\"Luke.19.46\"></r> <r v=\"Luke.22.52\"></r>, <r v=\"John.10.1\"></r>, <r v=\"John.10.8\"></r> <r v=\"John.18.40\"></r>, <r v=\"2Cor.11.26\"></r>.†</s> <sy><i>SYN.</i>: <g>κλέπτης</g>, q.v.</sy>"},"G3051":{"l":"λόγιον","o":4,"ar":"<f><o>λόγιον</o>، <g>-ου, τό</g></f> <s><b>وحي، قول إلهي</b>: <r v=\"Acts.7.38\"></r>، <r v=\"Rom.3.2\"></r>، <r v=\"Heb.5.12\"></r>، <r v=\"1Pet.4.11\"></r>.†</s>","en":"<f><o>λόγιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(dimin. of <g>λόγος</g>, v. <i>ICC</i>, <i>Ro.</i>, 70),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H565\">אִמְרָה</h>, <h n=\"H561\">אֵמֶר</h>, <r v=\"Ps.18.30\"></r> <r v=\"Ps.19.14\"></r>, al.; also for <h n=\"H1697\">דָּבָר</h>, <r v=\"Isa.28.13\"></r>, al.; (cf. <g>λογεῖον</g> (<g>-ιον</g>), for <h n=\"H2833\">חֹשֶׁן</h>, <i>the oracular breastplate</i> of the H.P., <r v=\"Exod.28.15\"></r>, al.);]</e> </et> <s><b>an oracle</b>: <r v=\"Acts.7.38\"></r>, <r v=\"Rom.3.2\"></r>, <r v=\"Heb.5.12\"></r>, <r v=\"1Pet.4.11\"></r> (on the eccl., <g>λόγια τ. Κυρίου</g>, v. Lft., <i>Essay on Sup. Rel.</i>, 172 ff.).†</s>"},"G3005":{"l":"λεῖμμα","o":1,"ar":"<f><o>λεῖμμα</o>، <g>-τος, τό</g></f> <s><b>بقيّة</b>: <r v=\"Rom.11.5\"></r>.†</s>","en":"<f><o>λεῖμμα</o> (WH, <g>λίμμα</g>, v. their <i>App.</i>, 154), <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>λείπω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.19.4\"></r> A (<h n=\"H7611\">שְׁאֵרִית</h>)*;]</e> </et> <s><b>a remnant</b>: <r v=\"Rom.11.5\"></r>.†</s>"},"G3048":{"l":"λογεία","o":2,"ar":"<f><o>λογεία</o>، انظر تحت مدخل <g>λογία</g>.</f>","en":"<f><o>λογεία</o>, v.s. <g>λογία</g>.</f>"},"G3084":{"l":"λυτρόω","o":3,"ar":"<f><o>λυτρόω</o>، <g>-ῶ</g></f> <s><b>يُطلق مقابل فدية</b>؛ في الصيغة الوسطى: <b>يُطلق بدفع فدية</b>، <b>يفدي</b>: بالمعنى الروحي، <r v=\"Titus.2.14\"></r>؛ في المبني للمجهول، <r v=\"1Pet.1.18\"></r>؛ وبالمعنى العام: <b>ينقذ</b> (قارن <r v=\"Exod.6.6\"></r>، <r v=\"Ps.69.18\"></r>، وفي مواضع أخرى): <r v=\"Luke.24.21\"></r>.†</s>","en":"<f><o>λυτρόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>λύτρον</g>, q.v.),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6299\">פּדה</h>, <h n=\"H1350\">גּאל</h>;]</e> </et> <s><b>to release on receipt of ransom</b>; mid., <b>to release by paying ransom</b>, <b>to redeem</b>: in spiritual sense, <r v=\"Titus.2.14\"></r>; pass, <r v=\"1Pet.1.18\"></r>; in general sense, <b>to deliver</b> (cf. <r v=\"Exod.6.6\"></r>, <r v=\"Ps.69.18\"></r>, al.): <r v=\"Luke.24.21\"></r>.†</s>"},"G3023":{"l":"λέων","o":9,"ar":"<f><o>λέων</o>، <g>-οντος, ὁ</g>،</f> <s><b>أسد</b>: <r v=\"Heb.11.33\"></r>، <r v=\"1Pet.5.8\"></r>، <r v=\"Rev.4.7\"></r> <r v=\"Rev.9.8\"></r>، <r v=\"Rev.9.17\"></r> <r v=\"Rev.10.3\"></r> <r v=\"Rev.13.2\"></r>؛ مجازيًا، <r v=\"2Tim.4.17\"></r>، <r v=\"Rev.5.5\"></r>.†</s>","en":"<f><o>λέων</o>, <g>-οντος, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H738\">אֲרִי</h>, <h n=\"H744\">אַרְיֵה</h>, also for <h n=\"H3715\">כְּפִיר</h>, etc.;]</e> </et> <s><b>a lion</b>: <r v=\"Heb.11.33\"></r>, <r v=\"1Pet.5.8\"></r>, <r v=\"Rev.4.7\"></r> <r v=\"Rev.9.8\"></r>, <r v=\"Rev.9.17\"></r> <r v=\"Rev.10.3\"></r> <r v=\"Rev.13.2\"></r>; metaph., <r v=\"2Tim.4.17\"></r>, <r v=\"Rev.5.5\"></r>.†</s>"},"G3001":{"l":"λάχανον","o":4,"ar":"<f><o>λάχανον</o>، <g>-ου, τό</g></f> <s><b>بَقْل</b>، <b>خُضَر</b>: <r v=\"Luke.11.42\"></r>؛ وعادةً في الجمع: <r v=\"Matt.13.32\"></r>، <r v=\"Mark.4.32\"></r>، <r v=\"Rom.14.2\"></r>.†</s>","en":"<f><o>λάχανον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(<g>λαχαίνω</g>, <i>to dig</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.9.3\"></r>, <r v=\"1Kgs.21.2\"></r>, <r v=\"Ps.37.2\"></r>, <r v=\"Prov.15.17\"></r> (<h n=\"H3418\">יֶרֶק</h>, <h n=\"H3419\">יָרָק</h>)*;]</e> </et> <s><b>a garden herb</b>, <b>vegetable</b>: <r v=\"Luke.11.42\"></r>; usually in pl., <r v=\"Matt.13.32\"></r>, <r v=\"Mark.4.32\"></r>, <r v=\"Rom.14.2\"></r>.†</s> <sy><i>SYN.</i>: <g>βοτάνη</g>, q.v.</sy>"},"G3011":{"l":"λειτουργός","o":5,"ar":"<f><o>λειτουργός</o>، <g>-οῦ, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>من يقوم بخدمة عامة على نفقته الخاصة</b>، ثم بوجه عام، </s> <s n=\"2.\"><b>موظَّف عام</b>، <b>خادم في العبادة</b>، <b>خادم</b>: <g>τ. ἁγίων λ.</g>، <r v=\"Heb.8.2\"></r> (قارن <r v=\"Neh.10.39\"></r>، <r v=\"Sir.7.30\"></r>)؛ <g>Ἰησοῦ Χριστοῦ</g>، <r v=\"Rom.15.16\"></r>؛ جمع، <g>τ. θεοῦ</g>، <r v=\"Rom.13.6\"></r>، <r v=\"Heb.1.7\"></r><i>(السبعينية)</i>؛ <g>λ. ὑμῶν τ. χρείας μου</g>، <r v=\"Phil.2.25\"></r>.†</s>","en":"<f><o>λειτουργός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>λιός</g>, <g>ἔργον</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8334\">מְשָׁרֵת</h>, <r v=\"Josh.1.1\"></r> A, <r v=\"1Kgs.10.5\"></r>, <r v=\"Ps.103.21\"></r>, <r v=\"Sir.7.30\"></r>, al.;]</e> </et> <s n=\"1.\">in cl., <b>one who discharges a public office at his own expense</b>, then, generally, </s> <s n=\"2.\"><b>a public servant</b>, <b>a minister</b>, <b>servant</b>: <g>τ. ἁγίων λ.</g>, <r v=\"Heb.8.2\"></r> (cf. <r v=\"Neh.10.39\"></r>, <r v=\"Sir.7.30\"></r>); <g>Ἰησοῦ Χριστοῦ</g>, <r v=\"Rom.15.16\"></r>; pl., <g>τ. θεοῦ</g>, <r v=\"Rom.13.6\"></r>, <r v=\"Heb.1.7\"></r><i>(LXX)</i>; <g>λ. ὑμῶν τ. χρείας μου</g>, <r v=\"Phil.2.25\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>διάκονος</g>, <g>λειτουργέω</g>.</sy>"},"G3034":{"l":"λιθάζω","o":9,"ar":"<f><o>λιθάζω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يرمي بالحجارة</b>.</s> <s n=\"2.\">= <g>λιθοβολέω</g> (السبعينية، العهد الجديد)، <b>يرشق بالحجارة</b>، <b>يرجم</b>: مع المنصوب للشخص، <r v=\"John.8.5\"></r> <r v=\"John.10.31-John.10.33\"></r> <r v=\"John.11.8\"></r>، <r v=\"Acts.14.10\"></r>؛ المبني للمجهول، <r v=\"Acts.5.26\"></r>، <r v=\"2Cor.11.25\"></r>، <r v=\"Heb.11.37\"></r> (قارن <g>κατα-λιθάζω</g>).†</s>","en":"<f><o>λιθάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>λίθος</g>),</e> <e t=\"septuagint\">[in LXX (seq. <g>ἐν λίθοις</g>): <r v=\"2Sam.16.6\"></r>, <r v=\"2Sam.16.13\"></r> (<h n=\"H5619\">סקל</h> pi.)*;]</e> </et> <s n=\"1.\"><b>to throw stones</b> (Arist., Polyb., al.).</s> <s n=\"2.\">= <g>λιθοβολέω</g> (LXX, NT), <b>to pelt with stones</b>, <b>to stone</b>: c. acc. pers., <r v=\"John.8.5\"></r> <r v=\"John.10.31-John.10.33\"></r> <r v=\"John.11.8\"></r>, <r v=\"Acts.14.10\"></r>; pass., <r v=\"Acts.5.26\"></r>, <r v=\"2Cor.11.25\"></r>, <r v=\"Heb.11.37\"></r> (v. <i>DB</i>, Art., \"Crimes and punishments,\" and cf. <g>κατα-λιθάζω</g>).†</s>"},"G3054":{"l":"λογομαχέω","o":1,"ar":"<f>*† <o>λογομαχέω</o>، <g>-ῶ</g></f> <s><b>يتماحك بالكلام</b>: <r v=\"2Tim.2.14\"></r>.†</s>","en":"<f>*† <o>λογομαχέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>λόγος</g>, <g>μάχομαι</g>),</e> </et> <s><b>to strive with words</b>: <r v=\"2Tim.2.14\"></r>.†</s>"},"G3082":{"l":"λύστρα","o":6,"ar":"<f><o>λύστρα</o>، <g>-ας, ἡ</g>، و(في <r v=\"Acts.14.8\"></r> <r v=\"Acts.16.2\"></r>، <r v=\"2Tim.3.11\"></r>) <g>-ων, τά</g> (قارن <g>Λύδδα</g>)،</f> <s><b>لسترة</b>، مدينة في ليكأونية: <r v=\"Acts.14.6\"></r>، <r v=\"Acts.14.8\"></r>، <r v=\"Acts.14.21\"></r> <r v=\"Acts.16.1\"></r>، <r v=\"Acts.16.2\"></r>، <r v=\"2Tim.3.11\"></r>.†</s>","en":"<f><o>λύστρα</o>, <g>-ας, ἡ</g>, and (in <r v=\"Acts.14.8\"></r> <r v=\"Acts.16.2\"></r>, <r v=\"2Tim.3.11\"></r>) <g>-ων, τά</g> (cf. <g>Λύδδα</g>),</f> <s><b>Lystra</b>, a city of Lycaonia: <r v=\"Acts.14.6\"></r>, <r v=\"Acts.14.8\"></r>, <r v=\"Acts.14.21\"></r> <r v=\"Acts.16.1\"></r>, <r v=\"Acts.16.2\"></r>, <r v=\"2Tim.3.11\"></r>.†</s>"},"G3058":{"l":"λοιδορέω","o":4,"ar":"<f><o>λοιδορέω</o>، <g>-ῶ</g></f> <s><b>شتم</b>، <b>عيّر</b>: مع المنصوب للشخص، <r v=\"John.9.28\"></r>، <r v=\"Acts.23.4\"></r>؛ المبني للمجهول، <r v=\"1Cor.4.12\"></r>، <r v=\"1Pet.2.23\"></r> (قارن <g>ἀντι-λοιδορέω</g>).†</s>","en":"<f><o>λοιδορέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>λοίδορος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7378\">רִיב</h>;]</e> </et> <s><b>to abuse</b>, <b>revile</b>: c. acc. pers., <r v=\"John.9.28\"></r>, <r v=\"Acts.23.4\"></r>; pass., <r v=\"1Cor.4.12\"></r>, <r v=\"1Pet.2.23\"></r> (cf. <g>ἀντι-λοιδορέω</g>).†</s>"},"G3060":{"l":"λοίδορος","o":2,"ar":"<f><o>λοίδορος</o>، <g>-ον</g>،</f> <s><b>شتّام</b>، <b>سليط اللسان</b>؛ وبمعنى الاسم <g>ὁ λ.</g>: <b>شتّام</b>: <r v=\"1Cor.5.11\"></r> <r v=\"1Cor.6.10\"></r>.†</s>","en":"<f><o>λοίδορος</o>, <g>-ον</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.25.24\"></r> <r v=\"Prov.26.21\"></r> <r v=\"Prov.27.15\"></r> (<h n=\"H4079\">מִדְיָן</h>) <r v=\"Sir.23.8\"></r>*;]</e> </et> <s><b>railing</b>, <b>abusive</b>; as subst., <g>ὁ λ.</g>, <b>a railer</b>: <r v=\"1Cor.5.11\"></r> <r v=\"1Cor.6.10\"></r>.†</s>"},"G3080":{"l":"λύσις","o":1,"ar":"<f><o>λύσις</o>، <g>-εως, ἡ</g></f> <s><b>انحلال، فكّ</b>: عن الطلاق، <r v=\"1Cor.7.27\"></r>.†</s>","en":"<f><o>λύσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λύω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Eccl.7.30\"></r> (<r v=\"Eccl.8.1\"></r>) (<h n=\"H6592\">פֵּשֶׁר</h>), <r v=\"Dan.12.8\"></r>, <r v=\"Wis.8.8\"></r>*;]</e> </et> <s><b>a loosing</b>: of divorce, <r v=\"1Cor.7.27\"></r>.†</s>"},"G3042":{"l":"λιμός","o":12,"ar":"<f><o>λιμός</o>، <g>-οῦ, ὁ</g></f> <s><b>جوع</b>، <b>مجاعة</b>: <r v=\"Luke.4.25\"></r> <r v=\"Luke.15.14\"></r>، <r v=\"Luke.15.17\"></r>، <r v=\"Acts.7.11\"></r> <i>(السبعينية)</i> <r v=\"Acts.11.28\"></r>، <r v=\"Rom.8.35\"></r>، <r v=\"Rev.6.8\"></r> <r v=\"Rev.18.8\"></r>؛ <g>λ. καὶ δίψος</g>، <r v=\"2Cor.11.27\"></r>؛ وفي الجمع: <r v=\"Matt.24.7\"></r>، <r v=\"Mark.13.8\"></r>، <r v=\"Luke.21.11\"></r>.†</s>","en":"<f><o>λιμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(so in Att.; in Dor. <g>ἡ</g>, and so sometimes in LXX, v. Th., <i>Gr.</i>, 146; in NT: <r v=\"Luke.15.14\"></r>, <r v=\"Acts.11.28\"></r>; cf. M, <i>Pr.</i>, 60),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7458\">רָעָב</h>;]</e> </et> <s><b>hunger</b>, <b>famine</b>: <r v=\"Luke.4.25\"></r> <r v=\"Luke.15.14\"></r>, <r v=\"Luke.15.17\"></r>, <r v=\"Acts.7.11\"></r><i>(LXX)</i> <r v=\"Acts.11.28\"></r>, <r v=\"Rom.8.35\"></r>, <r v=\"Rev.6.8\"></r> <r v=\"Rev.18.8\"></r>; <g>λ. καὶ δίψος</g>, <r v=\"2Cor.11.27\"></r>; pl., <r v=\"Matt.24.7\"></r>, <r v=\"Mark.13.8\"></r>, <r v=\"Luke.21.11\"></r>.†</s>"},"G3090":{"l":"Λωίς","o":1,"ar":"<f><o>Λωίς</o>، <g>-ίδος, ἡ</g>،</f> <s><b>لوئيس</b>: <r v=\"2Tim.1.5\"></r>.†</s>","en":"<f><o>Λωίς</o> (Rec. <g>Λωΐς</g>), <g>-ίδος, ἡ</g>,</f> <s><b>Lois</b>: <r v=\"2Tim.1.5\"></r>.†</s>"},"G3030":{"l":"λίβανος","o":2,"ar":"<f><o>λίβανος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>شجرة اللُّبان</b>.</s> <s n=\"2.\">(وأحيانًا في الكلاسيكية) <b>لُبان</b> (وكذلك في <r v=\"Lev.2.1\"></r>؛ قارن <g>λιβανωτός</g>): <r v=\"Matt.2.11\"></r>، <r v=\"Rev.18.13\"></r>.†</s>","en":"<f><o>λίβανος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(rarely <g>ἡ</g>), (from the Semitic; cf. the Heb. equiv.),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3828\">לְבֹנָה</h> <r v=\"Exod.30.34\"></r>, <r v=\"Isa.60.6\"></r>, <r v=\"Sir.24.15\"></r>, al.;]</e> </et> <s n=\"1.\">in cl., <b>the frankincense-tree</b>.</s> <s n=\"2.\">(Occas. in cl.) <b>frankincense</b> (so <r v=\"Lev.2.1\"></r>; cf. <g>λιβανωτός</g>): <r v=\"Matt.2.11\"></r>, <r v=\"Rev.18.13\"></r>.†</s>"},"G3021":{"l":"λευκαίνω","o":2,"ar":"<f><o>λευκαίνω</o></f> <s><b>بيّض</b>، <b>جعله أبيض</b>: مع منصوب الشيء، <r v=\"Mark.9.3\"></r>، <r v=\"Rev.7.14\"></r>.†</s>","en":"<f><o>λευκαίνω</o></f> <et> <e t=\"derivation\">(&lt; <g>λευκός</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.51.7\"></r>, <r v=\"Isa.1.18\"></r> (<h n=\"H3835\">לבן</h> hi.), etc.;]</e> </et> <s><b>to whiten</b>, <b>make white</b>: c. acc. rei, <r v=\"Mark.9.3\"></r>, <r v=\"Rev.7.14\"></r>.†</s>"},"G3041":{"l":"λίμνη","o":11,"ar":"<f><o>λίμνη</o>، <g>-ης, ἡ</g>،</f> <s><b>بحيرة</b>: عن بحر الجليل (يسمّيه متى ومرقس <g>θάλασσα</g>، انظر تحت المدخل)، <r v=\"Luke.5.2\"></r> <r v=\"Luke.8.22\"></r>، <r v=\"Luke.8.23\"></r>، <r v=\"Luke.8.33\"></r>؛ <g>λ. Γεννησαρέτ</g> (انظره)، <r v=\"Luke.5.1\"></r>؛ <g>λ. τ. πυρός</g>، <r v=\"Rev.19.20\"></r> <r v=\"Rev.20.10\"></r>، <r v=\"Rev.20.14\"></r>، <r v=\"Rev.20.15\"></r>؛ <g>καιομένη πυρί</g>، <r v=\"Rev.21.8\"></r>.†</s>","en":"<f><o>λίμνη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.107.35\"></r> <r v=\"Ps.114.8\"></r> (<h n=\"H98\">אֲגַם</h>), <r v=\"Song.7.4\"></r> (<r v=\"Song.7.5\"></r>) (<h n=\"H1295\">בְּרֵכָה</h>) <r v=\"1Macc.11.35\"></r>, <r v=\"2Macc.12.16\"></r>*;]</e> </et> <s><b>a lake</b>: of the Sea of Galilee (Mt, Mk, v.s. <g>θάλασσα</g>), <r v=\"Luke.5.2\"></r> <r v=\"Luke.8.22\"></r>, <r v=\"Luke.8.23\"></r>, <r v=\"Luke.8.33\"></r>; <g>λ. Γεννησαρέτ</g> (q.v.), <r v=\"Luke.5.1\"></r>; <g>λ. τ. πυρός</g>, <r v=\"Rev.19.20\"></r> <r v=\"Rev.20.10\"></r>, <r v=\"Rev.20.14\"></r>, <r v=\"Rev.20.15\"></r>; <g>καιομένη πυρί</g>, <r v=\"Rev.21.8\"></r>.†</s>"},"G3098":{"l":"Μαγώγ","o":1,"ar":"<f><o>Μαγώγ</o>، <g>ὁ</g>، لا يُصرَّف (بالعبرية <h n=\"H4031\">מָגוֹג</h>، <r v=\"Gen.10.2\"></r>، <r v=\"Exod.38.2\"></r>، وفي مواضع أخرى)،</f> <s><b>ماجوج</b>، مقرونًا بجوج: <r v=\"Rev.20.8\"></r>.†</s>","en":"<f><o>Μαγώγ</o>, <g>ὁ</g>, indecl. (Heb. <h n=\"H4031\">מָגוֹג</h>, <r v=\"Gen.10.2\"></r>, <r v=\"Exod.38.2\"></r>, al.),</f> <s><b>Magog</b>, associated with Gog: <r v=\"Rev.20.8\"></r> (v. Swete, in l.).†</s>"},"G3045":{"l":"λιπαρός","o":1,"ar":"<f><o>λιπαρός</o>، <g>-ά, -όν</g></f> <s><b>دسم</b>، <b>سمين</b>؛ مجازيًا، عن المعيشة، <b>مترف</b>، <b>شهيّ</b>: <g>τὰ λ. καὶ τ. λαμπρά</g>، <r v=\"Rev.18.14\"></r>.†</s>","en":"<f><o>λιπαρός</o>, <g>-ά, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>λίπος</g>, <i>fat</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.3.29\"></r>, <r v=\"Neh.9.35\"></r>, <r v=\"Isa.30.23\"></r> <r v=\"Isa.30.23\"></r> (<h n=\"H8082\">שָׁמֵן</h>)*;]</e> </et> <s><b>oily</b>, <b>fatty</b>; metaph., of living, <b>rich</b>, <b>dainty</b>: <g>τὰ λ. καὶ τ. λαμπρά</g>, <r v=\"Rev.18.14\"></r>.†</s>"},"G3088":{"l":"λύχνος","o":14,"ar":"<f><o>λύχνος</o>، <g>-ου, ὁ</g>،</f> <s><b>سراج</b> (محمول، يوضع عادةً على منارة، <g>λυχνία</g>): <r v=\"Matt.5.15\"></r>، <r v=\"Luke.11.36\"></r>؛ <g>ἔρχεται ὁ λ.</g>، <r v=\"Mark.4.21\"></r>؛ <g>λ. ἅπτειν</g>، <r v=\"Luke.8.16\"></r>، <r v=\"Luke.11.33\"></r>، <r v=\"Luke.15.8\"></r>؛ <g>φῶς λύχνου</g>، <r v=\"Rev.18.23\"></r>؛ ونفسه عكس <g>φ. ἡλίου</g>، <r v=\"Rev.22.5\"></r>؛ مجازيًا، عن العين، <r v=\"Matt.6.22\"></r>، <r v=\"Luke.11.34\"></r>؛ عن يوحنا المعمدان، <r v=\"John.5.35\"></r>؛ عن الخروف، <r v=\"Rev.21.23\"></r>؛ عن النبوة، <r v=\"2Pet.1.19\"></r>؛ عن الاستعداد الروحي، في الجمع، <g>λύχνοι</g> (كما دائمًا في السبعينية)، <r v=\"Luke.12.35\"></r>.†</s>","en":"<f><o>λύχνος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5216\">נֵר</h> (<r v=\"Exod.25.36\"></r> (<r v=\"Exod.25.37\"></r>), al.);]</e> </et> <s><b>a lamp</b> (portable, and usually set on a stand, <g>λυχνία</g>): <r v=\"Matt.5.15\"></r>, <r v=\"Luke.11.36\"></r>; <g>ἔρχεται ὁ λ.</g>, <r v=\"Mark.4.21\"></r>; <g>λ. ἅπτειν</g>, <r v=\"Luke.8.16\"></r> <r v=\"Luke.11.33\"></r> <r v=\"Luke.15.8\"></r>; <g>φῶς λύχνου</g>, <r v=\"Rev.18.23\"></r>; id. opp. to <g>φ. ἡλίου</g>, <r v=\"Rev.22.5\"></r>; metaph., of the eye, <r v=\"Matt.6.22\"></r>, <r v=\"Luke.11.34\"></r>; of John the Baptist, <r v=\"John.5.35\"></r>; of the Lamb, <r v=\"Rev.21.23\"></r>; of prophecy, <r v=\"2Pet.1.19\"></r>; of spiritual readiness, pl., <g>λύχνοι</g> (as always in LXX; freq. in Att. <g>λύχνα</g>), <r v=\"Luke.12.35\"></r>.†</s> <sy><i>SYN.</i>: <g>λαμπάς</g>, q.v.</sy>"},"G3085":{"l":"λύτρωσις","o":3,"ar":"<f>† <o>λύτρωσις</o>، <g>-εως, ἡ</g></f> <s><b>فِدية، فداء</b>: عن عمل المسيح الوسيط، <r v=\"Heb.9.12\"></r>؛ وبالمعنى العام، <b>خلاص، إنقاذ</b> (قارن <r v=\"Ps.49.8\"></r>): <r v=\"Luke.1.68\"></r>، <r v=\"Luke.2.38\"></r>.†</s>","en":"<f>† <o>λύτρωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λυτρόω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.25.29\"></r>, <r v=\"Lev.25.48\"></r>, <r v=\"Isa.63.4\"></r> <h n=\"H1353\">גְּאֻלִים</h>, <h n=\"H1353\">גְּאֻלָּה</h>), <r v=\"Num.18.16\"></r>, <r v=\"Ps.49.8\"></r> <r v=\"Ps.111.9\"></r> <r v=\"Ps.130.7\"></r> (<h n=\"H6299\">פָּדָה</h>, <h n=\"????\">פִּדְיֹן</h>, <h n=\"H6304\">פְּדוּת</h>), <r v=\"Judg.1.15\"></r>*;]</e> </et> <s><b>a ransoming</b>, <b>redemption</b> (<g>αἰχμαλώτων</g>, Plut., <i>Arat.</i>, 11): of the mediatorial work of Christ, <r v=\"Heb.9.12\"></r>; in general sense, <b>deliverance</b> (cf. <r v=\"Ps.49.8\"></r>): <r v=\"Luke.1.68\"></r> <r v=\"Luke.2.38\"></r>.†</s>"},"G3010":{"l":"λειτουργικός","o":1,"ar":"<f>† <o>λειτουργικός</o>، <g>-ή, -όν</g>،</f> <s><b>خادم</b> أو <b>للخدمة</b>، <b>مُتعلّق بالخدمة</b>: <g>πνεύματα</g>، <r v=\"Heb.1.14\"></r>.†</s>","en":"<f>† <o>λειτουργικός</o>, <g>-ή, -όν</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5656\">עֲבֹדָה</h>, <h n=\"H8334\">שָׁרֵת</h>; <g>ἔργα</g>, <r v=\"Num.7.5\"></r>; <g>στολαί</g>, <r v=\"Exod.31.9\"></r> (<r v=\"Exod.31.10\"></r>) <r v=\"Exod.39.13\"></r> (<r v=\"Exod.39.1\"></r>); <g>σκευή</g>, <r v=\"Num.4.12\"></r>, <r v=\"Num.4.26\"></r>, <r v=\"2Chr.24.14\"></r>*;]</e> </et> <s><b>of</b> or <b>for service</b>, <b>ministering</b>: <g>πνεύματα</g>, <r v=\"Heb.1.14\"></r>.†</s>"},"G3024":{"l":"λήθη","o":1,"ar":"<f><o>λήθη</o>، <g>-ης, ἡ</g></f> <s><b>نسيان</b>: <g>λ. λαβεῖν</g>: <r v=\"2Pet.1.9\"></r>.†</s>","en":"<f><o>λήθη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λήθω</g> = <g>λανθάνω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.5.15\"></r> (<h n=\"H4604\">מַעַל</h>), <r v=\"Wis.16.11\"></r>, <r v=\"Sir.14.7\"></r>, al.;]</e> </et> <s><b>forgetfulness</b>: <g>λ. λαβεῖν</g> (on the phrase, v. Mayor, in l.): <r v=\"2Pet.1.9\"></r>.†</s>"},"G3022":{"l":"λευκός","o":25,"ar":"<f><o>λευκός</o>، <g>ή, -όν</g>،</f> <s n=\"1.\"><b>لامع</b>، <b>برّاق</b>: عن الثياب، <r v=\"Matt.17.2\"></r>، <r v=\"Mark.9.3\"></r> <r v=\"Mark.16.5\"></r>، <r v=\"Luke.9.29\"></r>، <r v=\"Acts.1.10\"></r>، <r v=\"Rev.3.5\"></r> <r v=\"Rev.4.4\"></r> <r v=\"Rev.6.11\"></r> <r v=\"Rev.7.9\"></r>، <r v=\"Rev.7.13\"></r> <r v=\"Rev.19.14\"></r> (قارن <r v=\"Eccl.9.8\"></r>)؛ <g>ὡς χιών</g>، <r v=\"Matt.28.3\"></r>؛ <g>ἐν λ.</g> (أي <g>ἱματίοις</g>)، <r v=\"John.20.12\"></r>، <r v=\"Rev.3.4\"></r>؛ <g>θρόνος</g>، <r v=\"Rev.20.11\"></r>.</s> <s n=\"2.\"><b>أبيض</b>: <r v=\"Matt.5.36\"></r>، <r v=\"Rev.1.14\"></r> <r v=\"Rev.2.17\"></r> <r v=\"Rev.4.4\"></r> <r v=\"Rev.6.2\"></r> <r v=\"Rev.14.14\"></r> <r v=\"Rev.19.11\"></r>؛ مجازيًا، عن الثياب، <r v=\"Rev.3.18\"></r>؛ وعن الزرع الناضج، <r v=\"John.4.35\"></r>.†</s>","en":"<f><o>λευκός</o>, <g>ή, -όν</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3836\">לָבָן</h>;]</e> </et> <s n=\"1.\"><b>bright</b>, <b>brilliant</b>: of clothing, <r v=\"Matt.17.2\"></r>, <r v=\"Mark.9.3\"></r> <r v=\"Mark.16.5\"></r>, <r v=\"Luke.9.29\"></r>, <r v=\"Acts.1.10\"></r>, <r v=\"Rev.3.5\"></r> <r v=\"Rev.4.4\"></r> <r v=\"Rev.6.11\"></r> <r v=\"Rev.7.9\"></r>, <r v=\"Rev.7.13\"></r> <r v=\"Rev.19.14\"></r> (cf. <r v=\"Eccl.9.8\"></r>); <g>ὡς χιών</g>, <r v=\"Matt.28.3\"></r>; <g>ἐν λ.</g> (sc. <g>ἱματίοις</g>), <r v=\"John.20.12\"></r>, <r v=\"Rev.3.4\"></r>; <g>θρόνος</g>, <r v=\"Rev.20.11\"></r>.</s> <s n=\"2.\"><b>white</b>: <r v=\"Matt.5.36\"></r>, <r v=\"Rev.1.14\"></r> <r v=\"Rev.2.17\"></r> <r v=\"Rev.4.4\"></r> <r v=\"Rev.6.2\"></r> <r v=\"Rev.14.14\"></r> <r v=\"Rev.19.11\"></r>; fig., of garments, <r v=\"Rev.3.18\"></r>; of ripened grain, <r v=\"John.4.35\"></r>.†</s>"},"G3087":{"l":"λυχνία","o":12,"ar":"<f><o>λυχνία</o>، <g>-ας, ἡ</g></f> <s><b>منارة</b>: <r v=\"Matt.5.15\"></r>، <r v=\"Mark.4.21\"></r>، <r v=\"Luke.8.16\"></r> <r v=\"Luke.11.33\"></r>؛ عن منارة خيمة الاجتماع، <r v=\"Heb.9.2\"></r>؛ مجازيًا، عن الشاهدين، <r v=\"Rev.11.4\"></r>؛ وعن الكنائس السبع في أسيا، <r v=\"Rev.1.12\"></r>، <r v=\"Rev.1.13\"></r>، <r v=\"Rev.1.20\"></r> <r v=\"Rev.2.1\"></r>؛ وعن زحزحة الكنيسة من مكانها، <g>κινεῖν τ. λυχνίαν κ.τ.λ.</g>، <r v=\"Rev.2.5\"></r>.†</s>","en":"<f><o>λυχνία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(vulgar form of <g>λυχνίον</g> = <g>λυχνοῦχος</g>; v. Kennedy, <i>Sources</i>, 40),</e> <e t=\"septuagint\">[in LXX for <h n=\"H4501\">מְנוֹרָה</h> (<r v=\"Exod.25.31\"></r> <r v=\"Exod.40.4\"></r>, al.);]</e> </et> <s><b>a lampstand</b>: <r v=\"Matt.5.15\"></r>, <r v=\"Mark.4.21\"></r>, <r v=\"Luke.8.16\"></r> <r v=\"Luke.11.33\"></r>; of that in the Tabernacle, <r v=\"Heb.9.2\"></r>; metaph., of the two witnesses, <r v=\"Rev.11.4\"></r>; of the seven churches of Asia, <r v=\"Rev.1.12\"></r>, <r v=\"Rev.1.13\"></r>, <r v=\"Rev.1.20\"></r> <r v=\"Rev.2.1\"></r>; of the removal of a church from its position, <g>κινεῖν τ. λυχνίαν κ.τ.λ.</g>, <r v=\"Rev.2.5\"></r>.†</s>"},"G3068":{"l":"λούω","o":5,"ar":"<f><o>λούω</o>،</f> <s><b>حمّم</b>، <b>غسل</b> الجسد: مع منصوب الشخص، <r v=\"Acts.9.37\"></r> (عن جسد ميت)؛ وكذلك يليه <g>ἀπό</g>، <r v=\"Acts.16.33\"></r>؛ اسم المفعول التام، <r v=\"John.13.10\"></r>، <r v=\"Heb.10.22\"></r>؛ الصيغة الوسطى: <b>اغتسل</b>، <r v=\"2Pet.2.22\"></r>؛ مجازيًا، <r v=\"Rev.1.5\"></r> (قارن <g>ἀπο-λούω</g>).†</s>","en":"<f><o>λούω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7364\">רחץ</h> (freq. of ceremonial washing; cf. Deiss., <i>BS</i>, 226 f.);]</e> </et> <s><b>to bathe</b>, <b>wash</b> the body: c. acc. pers., <r v=\"Acts.9.37\"></r> (of a dead body); id. seq. <g>ἀπό</g> (Deiss., <i>BS</i>, 226 f.), <r v=\"Acts.16.33\"></r>; pass. ptcp. pf., <r v=\"John.13.10\"></r>, <r v=\"Heb.10.22\"></r>; mid., <b>to wash oneself</b> (Mayor, in l.; M. <i>Pr.</i>, 155 f., 238 f.), <r v=\"2Pet.2.22\"></r>; metaph., <r v=\"Rev.1.5\"></r>, Rec., R, mg. (cf. <g>ἀπο-λούω</g>).†</s> <sy><i>SYN.</i>: <g>νίπτω</g>, used of parts of the body-hands, feet, face; <g>πλύνω</g>, of things, as garments, etc. (v. <r v=\"Lev.15.11\"></r>; cf. Tr., <i>Syn.</i>, § xlv).</sy>"},"G3036":{"l":"λιθοβολέω","o":7,"ar":"<f>† <o>λιθο-βολέω</o>، <g>-ῶ</g></f> <s><b>رمى بالحجارة</b>، <b>قتل رجمًا</b>، <b>رجم</b> (قارن <g>λιθάζω</g>): مع منصوب الشخص، <r v=\"Matt.21.35\"></r> <r v=\"Matt.23.37\"></r>، <r v=\"Luke.13.34\"></r>، <r v=\"Acts.7.58\"></r>، <r v=\"Acts.7.59\"></r> <r v=\"Acts.14.5\"></r>؛ المبني للمجهول، <r v=\"Heb.12.20\"></r><i>(السبعينية)</i>.†</s>","en":"<f>† <o>λιθο-βολέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>λίθος</g>, <g>βάλλω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5619\">סקל</h>, <h n=\"H7275\">רגם</h>, <r v=\"Exod.19.13\"></r>, <r v=\"Lev.20.2\"></r>, al.;]</e> </et> <s><b>to pelt with stones</b>, <b>to kill by stoning</b>, <b>to stone</b> (cf. <g>λιθάζω</g>): c. acc. pers., <r v=\"Matt.21.35\"></r> <r v=\"Matt.23.37\"></r>, <r v=\"Luke.13.34\"></r>, <r v=\"Acts.7.58\"></r>, <r v=\"Acts.7.59\"></r> <r v=\"Acts.14.5\"></r>; pass., <r v=\"Heb.12.20\"></r><i>(LXX)</i>.†</s>"},"G3025":{"l":"ληνός","o":5,"ar":"<f><o>ληνός</o>، <g>-οῦ, ἡ</g></f> <s><b>حوض</b> أو <b>معصرة</b>؛ وخاصةً لدوس العنب: <r v=\"Matt.21.33\"></r>، <r v=\"Rev.14.20\"></r> <r v=\"Rev.19.16\"></r>؛ <g>τὴν λ. . . . τὸν μέγαν</g> (خطأ نحوي ربما غير مقصود)، <r v=\"Rev.14.19\"></r> (قارن <g>ὑπολήνιον</g>).†</s>","en":"<f><o>ληνός</o>, <g>-οῦ, ἡ</g></f> <et> <e t=\"derivation\">(in some MSS., LXX and NT, <g>ὁ</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3342\">יֶקֶב</h>, <r v=\"Num.18.27\"></r>, al.; also for <h n=\"H7298\">רַהַט</h> (<r v=\"Gen.30.38\"></r>, <r v=\"Gen.30.41\"></r>), <h n=\"H1660\">גַּת</h> (<r v=\"Neh.13.15\"></r>, al.), etc.;]</e> </et> <s><b>a trough</b> or <b>vat</b>; esp. for the treading of grapes: <r v=\"Matt.21.33\"></r>, <r v=\"Rev.14.20\"></r> <r v=\"Rev.19.16\"></r>; <g>τὴν λ. . . . τὸν μέγαν</g> (a solecism perhaps inadvertent), <r v=\"Rev.14.19\"></r> (cf. <g>ὑπολήνιον</g>).†</s>"},"G3091":{"l":"Λώτ","o":4,"ar":"<f><o>Λώτ</o>، <g>ὁ</g> (بالعبرية <h n=\"H3876\">לוֹט</h>)، لا يُصرَّف،</f> <s><b>لوط</b> (<r v=\"Gen.11.27\"></r>، وفي مواضع أخرى): <r v=\"Luke.17.28\"></r>، <r v=\"Luke.17.29\"></r>، <r v=\"Luke.17.32\"></r>، <r v=\"2Pet.2.7\"></r>.†</s>","en":"<f><o>Λώτ</o>, <g>ὁ</g> (Heb. <h n=\"H3876\">לוֹט</h>), indecl.,</f> <s><b>Lot</b> (<r v=\"Gen.11.27\"></r>, al.): <r v=\"Luke.17.28\"></r>, <r v=\"Luke.17.29\"></r>, <r v=\"Luke.17.32\"></r>, <r v=\"2Pet.2.7\"></r>.†</s>"},"G3043":{"l":"λίνον","o":2,"ar":"<f><o>λίνον</o></f> <s n=\"1.\"><b>كتّان</b>: <r v=\"Matt.12.20\"></r><i>(السبعينية)</i>.</s> <s n=\"2.\"><b>ثوب كتّان</b>: <r v=\"Rev.15.6\"></r>.†</s>","en":"<f><o>λίνον</o></f> <et> <e t=\"derivation\">(Tr. <g>λῖνον</g>), <g>-ου, τό</g>,</e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.9.31\"></r> (<h n=\"H6594\">פִּשְׁתָּה</h>), al.;]</e> </et> <s n=\"1.\"><b>flax</b>: <r v=\"Matt.12.20\"></r><i>(LXX)</i>.</s> <s n=\"2.\"><b>linen</b>: <r v=\"Rev.15.6\"></r> (R, mg., v.s. <g>λίθος</g>).†</s>"},"G3020":{"l":"Λευειτικός","o":1,"ar":"<f><o>Λευειτικός</o></f> <s><b>لاوي</b>: <r v=\"Heb.7.11\"></r>.†</s>","en":"<f><o>Λευειτικός</o></f> <et> <e t=\"derivation\">(Rec. <g>Λευϊτ-</g>), <g>-ή, -όν</g>,</e> <e t=\"septuagint\">[in LXX: Le, <i>tit.</i>*;]</e> </et> <s><b>Levitical</b>: <r v=\"Heb.7.11\"></r>.†</s>"},"G3017":{"l":"Λευεί","o":1,"ar":"<f><o>Λευεί</o> (لا يُصرَّف) و<g>Λευείς</g>، حالة الجر <g>Λευεί</g>، حالة النصب <g>-είν</g>، <g>ὁ</g> (بالعبرية <h n=\"H3878\">לֵוִי</h>)،</f> <s><b>لاوي</b>؛ <s n=\"1.\">ابن يعقوب: <r v=\"Heb.7.5\"></r>، <r v=\"Heb.7.9\"></r>، <r v=\"Rev.7.7\"></r>.</s> <s n=\"2.\">ابن ملكي: <r v=\"Luke.3.24\"></r>.</s> <s n=\"3.\">ابن شمعون: <r v=\"Luke.3.29\"></r>.</s> <s n=\"4.\">ابن حلفى (قارن <g>Μαθθαῖος</g>): <r v=\"Mark.2.14\"></r>، <r v=\"Luke.5.27\"></r>، <r v=\"Luke.5.29\"></r>.†</s> </s>","en":"<f><o>Λευεί</o> (indecl.) and <g>Λευείς</g> (Rec. <g>-υΐ</g>, <g>-υΐς</g>), gen. <g>Λευεί</g>, acc. <g>-είν</g>, <g>ὁ</g> (Heb. <h n=\"H3878\">לֵוִי</h>),</f> <s><b>Levi</b>; <s n=\"1.\">the son of Jacob: <r v=\"Heb.7.5\"></r>, <r v=\"Heb.7.9\"></r>, <r v=\"Rev.7.7\"></r>.</s> <s n=\"2.\">Son of Melchi: <r v=\"Luke.3.24\"></r>.</s> <s n=\"3.\">Son of Simeon: <r v=\"Luke.3.29\"></r>.</s> <s n=\"4.\">Son of Alphæus (cf. <g>Μαθθαῖος</g>): <r v=\"Mark.2.14\"></r> (WH, mg., <g>Ἰάκωβον</g>), <r v=\"Luke.5.27\"></r>, <r v=\"Luke.5.29\"></r>.†</s> </s>"},"G3031":{"l":"λιβανωτός","o":2,"ar":"<f><o>λιβανωτός</o>، <g>-οῦ, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية (وفي السبعينية): <b>لُبان، بخور</b>، صمغ <b>شجرة اللبان</b>.</s> <s n=\"2.\">= في اليونانية المتأخرة <g>λιβανωτρίς</g>، <b>مبخرة</b>: <r v=\"Rev.8.3\"></r>، <r v=\"Rev.8.5\"></r>.†</s>","en":"<f><o>λιβανωτός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>λίβανος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Chr.9.29\"></r>, (<h n=\"H3828\">לְבֹנָה</h>), <r v=\"3Macc.5.2\"></r>*;]</e> </et> <s n=\"1.\">in cl. (and LXX), <b>frankincense</b>, the gum of the <b>libanus</b>.</s> <s n=\"2.\">= Late Gk., <g>λιβανωτρίς</g>, <b>a censer</b>: <r v=\"Rev.8.3\"></r>, <r v=\"Rev.8.5\"></r> (the same form appears in Inscr.; MM, xvi).†</s>"},"G3081":{"l":"λυσιτελέω","o":1,"ar":"<f>** <o>λυσιτελέω</o>، <g>-ῶ</g></f> <s n=\"1.\">أصلاً، <b>عوَّض</b>، <b>دفع</b> <b>النفقات</b>.</s> <s n=\"2.\"><b>كان نافعًا</b>، <b>أفاد</b>؛ وعادةً غير شخصي، <g>λυσιτελεῖ</g>، <b>يُفيد، خيرٌ له</b>: مع قابل الشخص، يليه <g>εἰ . . . ἤ</g>، <r v=\"Luke.17.2\"></r>.†</s>","en":"<f>** <o>λυσιτελέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>λυσιτελής</g>, <i>useful</i>, prop., <g>τὰ τέλη λύων</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Tob.3.6\"></r>, <r v=\"Sir.20.10\"></r>, <r v=\"Sir.20.14\"></r> <r v=\"Sir.29.11\"></r>*;]</e> </et> <s n=\"1.\">prop., <b>to indemnify</b>, <b>pay</b> <b>expenses</b>.</s> <s n=\"2.\"><b>to be useful</b>, <b>to profit</b>; usually impers., <g>λυσιτελεῖ</g>, <b>it profits</b>: c, dat. pers., seq. <g>εἰ . . . ἤ</g>, <r v=\"Luke.17.2\"></r>.†</s>"},"G3079":{"l":"Λυσίας","o":2,"ar":"<f><o>Λυσίας</o>، <g>-ου, ὁ</g>،</f> <s><b>ليسياس</b> (<i>كلوديوس ليسياس</i>، <r v=\"Acts.23.26\"></r>)، <r v=\"Acts.24.7\"></r>، <r v=\"Acts.24.22\"></r>.†</s>","en":"<f><o>Λυσίας</o>, <g>-ου, ὁ</g>,</f> <s><b>Lysias</b> (<i>Claudius L.</i>, <r v=\"Acts.23.26\"></r>), <r v=\"Acts.24.7\"></r>, <r v=\"Acts.24.22\"></r>.†</s>"},"G3006":{"l":"λεῖος","o":1,"ar":"<f><o>λεῖος</o>، <g>-εία, -εῖον</g>،</f> <s><b>سهل، أملس</b>: عكس <g>τραχύς</g>، <r v=\"Luke.3.5\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>λεῖος</o>, <g>-εία, -εῖον</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.27.11\"></r>, <r v=\"1Sam.17.40\"></r> R (<h n=\"H2505\">חָלָק</h>, <h n=\"H2512\">חַלּוּק</h>); <g>ὁδὸς λ.</g>, <r v=\"Isa.40.4\"></r> <g>Α</g> (<h n=\"H1237\">בִּקְעָה</h>); <r v=\"Prov.2.20\"></r> <r v=\"Prov.12.13\"></r> <r v=\"Prov.26.23\"></r>*;]</e> </et> <s><b>smooth</b>: opp. to <g>τραχύς</g>, <r v=\"Luke.3.5\"></r><i>(LXX)</i>.†</s>"},"G3013":{"l":"λεπίς","o":1,"ar":"<f><o>λεπίς</o>، <g>-ίδος, ἡ</g></f> <s><b>قشرة</b>: <r v=\"Acts.9.18\"></r>.†</s>","en":"<f><o>λεπίς</o>, <g>-ίδος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λέπω</g>, <i>to peel</i>)</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7193\">קַשְׂקֶשֶׂת</h>;]</e> </et> <s><b>a scale</b>: <r v=\"Acts.9.18\"></r>.†</s>"},"G3083":{"l":"λύτρον","o":2,"ar":"<f><o>λύτρον</o>، <g>-ον, τό</g></f> <s><b>فدية</b> (عن نفسٍ، <r v=\"Exod.21.30\"></r>؛ عن العبيد، <r v=\"Lev.19.20\"></r>؛ عن الأسرى، <r v=\"Isa.45.13\"></r>): <g>ἀντὶ πολλῶν</g>، <r v=\"Matt.20.28\"></r>، <r v=\"Mark.10.45\"></r> (قارن أيضًا <g>ἀντί-λύτρον</g>).†</s>","en":"<f><o>λύτρον</o>, <g>-ον, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>λύω</g>),</e> <e t=\"septuagint\">[in LXX (Pent.<i>15</i>, Pr<i>2</i>, Isa<i>1</i>) for <h n=\"H6306\">פִּדְיוֹם</h> and cogn. forms, <h n=\"H1353\">גְּאֻלָּה</h>, <h n=\"H3724\">כֹּפֶר</h>, <h n=\"H4242\">מְחִיר</h>;]</e> </et> <s><b>a ransom</b> (as for a life, <r v=\"Exod.21.30\"></r>; for slaves, <r v=\"Lev.19.20\"></r>; for captives, <r v=\"Isa.45.13\"></r>): <g>ἀντὶ πολλῶν</g>, <r v=\"Matt.20.28\"></r>, <r v=\"Mark.10.45\"></r> (v. Swete, in l., and for discussion of <g>λ.</g> and its cognates, Westc., <i>He.</i>, 295 f.; Deiss., <i>LAE</i>, 331 f.; cf. also <g>ἀντί-λύτρον</g>).†</s>"},"G3032":{"l":"Λιβερτῖνος","o":1,"ar":"<f><o>Λιβερτῖνος</o>، <g>-ου, ὁ</g> (اللاتينية <l>libertinus</l>)،</f> <s><b>معتوق، مُحرَّر</b>: <g>ἡ συναγωγὴ ἡ λεγομένη Λιβερτίνων</g>، <r v=\"Acts.6.9\"></r>.†</s>","en":"<f><o>Λιβερτῖνος</o>, <g>-ου, ὁ</g> (Lat. <l>libertinus</l>),</f> <s><b>a freedman</b>: <g>ἡ συναγωγὴ ἡ λεγομένη Λιβερτίνων</g>, <r v=\"Acts.6.9\"></r> (Bl. thinks the original reading was <g>Λιβυστίνων</g>, <i>Phil. Gosp.</i>, 69 f.).†</s>"},"G3003":{"l":"λεγιών","o":4,"ar":"<f>*† <o>λεγιών</o>، <g>-ῶνος, ἡ</g>، (اللاتينية <l>legio</l>)،</f> <s><b>لجئون، فيلق</b>: <r v=\"Matt.26.53\"></r>، <r v=\"Mark.5.9\"></r>، <r v=\"Mark.5.15\"></r>، <r v=\"Luke.8.30\"></r>.†</s>","en":"<f>*† <o>λεγιών</o> (Rec. <g>-εών</g>), <g>-ῶνος, ἡ</g>, (Lat. <l>legio</l>),</f> <s><b>a legion</b>: <r v=\"Matt.26.53\"></r>, <r v=\"Mark.5.9\"></r>, <r v=\"Mark.5.15\"></r>, <r v=\"Luke.8.30\"></r>.†</s>"},"G3019":{"l":"Λευείτης","o":3,"ar":"<f><o>Λευείτης</o></f> <s><b>لاوي</b>: <r v=\"Luke.10.32\"></r>، <r v=\"John.1.19\"></r>، <r v=\"Acts.4.36\"></r>.†</s>","en":"<f><o>Λευείτης</o></f> <et> <e t=\"derivation\">(Rec. <g>Λευΐτης</g>), <g>-ου, ὁ</g>,</e> <e t=\"septuagint\">[in LXX for <h n=\"H3881\">לֵוִי</h>;]</e> </et> <s><b>a Levite</b>: <r v=\"Luke.10.32\"></r>, <r v=\"John.1.19\"></r>, <r v=\"Acts.4.36\"></r>.†</s>"},"G3071":{"l":"Λυκαονία","o":1,"ar":"<f><o>Λυκαονία</o>، <g>-ας, ἡ</g>،</f> <s><b>ليكأونية</b>، إقليم في آسيا الصغرى: <r v=\"Acts.14.6\"></r>.†</s>","en":"<f><o>Λυκαονία</o>, <g>-ας, ἡ</g>,</f> <s><b>Lycaonia</b>, a region in Asia Minor: <r v=\"Acts.14.6\"></r>.†</s>"},"G3073":{"l":"Λυκία","o":1,"ar":"<f><o>Λυκία</o>، <g>-ας, ἡ</g>،</f> <s><b>ليكية</b>، إقليم في آسيا الصغرى؛ <r v=\"Acts.27.5\"></r>.†</s>","en":"<f><o>Λυκία</o>, <g>-ας, ἡ</g>,</f> <s><b>Lydia</b>, a region of Asia Minor; <r v=\"Acts.27.5\"></r>.†</s>"},"G3039":{"l":"λικμάω","o":2,"ar":"<f><o>λικμάω</o>، <g>-ῶ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يذرّي</b> (وكذلك في <r v=\"Ruth.3.2\"></r>).</s> <s n=\"2.\">في السبعينية (<r v=\"1Kgs.14.15\"></r>، <r v=\"Isa.17.13\"></r>، <r v=\"Jer.31.10\"></r>، <r v=\"Dan.2.44\"></r>)، <b>يُذري، يبدّد</b> (كالتبن أو الغبار): <r v=\"Luke.20.18\"></r> (الترجمة المنقحة: <i>يذرّيه كالغبار</i>؛ وقد يعني <i>يسحق</i>، <i>يُهلك</i>؛ قارن الترجمة المعتمدة: <i>يطحنه</i>)، <r v=\"Matt.21.44\"></r>.†</s>","en":"<f><o>λικμάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>λικμός</g> = <g>λίκνον</g>, <i>a winnowing-fan</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2219\">זרה</h> ni., pi., <r v=\"Ruth.3.2\"></r>, <r v=\"1Kgs.14.15\"></r>, <r v=\"Isa.17.13\"></r>, <r v=\"Jer.31.10\"></r>, <r v=\"Dan.2.44\"></r>, al.;]</e> </et> <s n=\"1.\">in cl., <b>to winnow</b> (so <r v=\"Ruth.3.2\"></r>).</s> <s n=\"2.\">In LXX (<r v=\"1Kgs.14.15\"></r>, <r v=\"Isa.17.13\"></r>, <r v=\"Jer.31.10\"></r>, <r v=\"Dan.2.44\"></r>), <b>to scatter</b> (as chaff or dust): <r v=\"Luke.20.18\"></r> (RV, <i>scatter as dust</i>, Deiss., <i>BS</i>, 225 f., quotes ex. in <g>π.</g> which suggests the meaning <i>ruin</i>, <i>destroy</i>; cf. Vg. <l>comminuet</l>, AV, <i>grind to powder</i>; cf. also Kennedy, <i>Sources</i>, 126), <r v=\"Matt.21.44\"></r> [WH], R, txt.†</s>"},"G3046":{"l":"λίτρα","o":2,"ar":"<f>*† <o>λίτρα</o>، <g>-ας, ἡ</g></f> <s n=\"1.\">عملة صقلية = <b>الليبرا</b> أو <b>الآس</b> الروماني.</s> <s n=\"2.\">في الوزن، <b>رطل</b> (مَنًا): <r v=\"John.12.3\"></r> <r v=\"John.19.39\"></r>.†</s>","en":"<f>*† <o>λίτρα</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(cf. Lat. <l>libra</l>),</e> </et> <s n=\"1.\">a Sicilian coin = Rom. <b>libra</b> or <b>as</b>.</s> <s n=\"2.\">In weight, <b>a pound</b>: <r v=\"John.12.3\"></r> <r v=\"John.19.39\"></r>.†</s>"},"G3096":{"l":"μαγεύω","o":1,"ar":"<f>* <o>μαγεύω</o>،</f> <s n=\"1.\"><b>يكون مجوسيًا</b>، أو <b>ماهرًا في علوم المجوس</b>.</s> <s n=\"2.\"><b>يمارس السحر</b>: <r v=\"Acts.8.9\"></r>.†</s>","en":"<f>* <o>μαγεύω</o> (Eur., Plut., al.),</f> <s n=\"1.\"><b>to be a Magus</b>, or <b>skilled in Magian lore</b>.</s> <s n=\"2.\"><b>to practise magic</b>: <r v=\"Acts.8.9\"></r>.†</s>"},"G3070":{"l":"Λυδία","o":2,"ar":"<f><o>Λυδία</o>، <g>-ας, ἡ</g>،</f> <s><b>ليدية</b>، امرأة من ثياتيرا: <r v=\"Acts.16.14\"></r>، <r v=\"Acts.16.40\"></r>.†</s>","en":"<f><o>Λυδία</o>, <g>-ας, ἡ</g>,</f> <s><b>Lydia</b>, a woman of Thyatira: <r v=\"Acts.16.14\"></r>, <r v=\"Acts.16.40\"></r>.†</s>"},"G3018":{"l":"Λευεί","o":1,"ar":"<f><o>Λευεί</o> (لا يُصرَّف) و<g>Λευείς</g>، حالة الجر <g>Λευεί</g>، حالة النصب <g>-είν</g>، <g>ὁ</g> (بالعبرية <h n=\"H3878\">לֵוִי</h>)،</f> <s><b>لاوي</b>؛ <s n=\"1.\">ابن يعقوب: <r v=\"Heb.7.5\"></r>، <r v=\"Heb.7.9\"></r>، <r v=\"Rev.7.7\"></r>.</s> <s n=\"2.\">ابن ملكي: <r v=\"Luke.3.24\"></r>.</s> <s n=\"3.\">ابن شمعون: <r v=\"Luke.3.29\"></r>.</s> <s n=\"4.\">ابن حلفى (قارن <g>Μαθθαῖος</g>): <r v=\"Mark.2.14\"></r>، <r v=\"Luke.5.27\"></r>، <r v=\"Luke.5.29\"></r>.†</s> </s>","en":"<f><o>Λευεί</o> (indecl.) and <g>Λευείς</g> (Rec. <g>-υΐ</g>, <g>-υΐς</g>), gen. <g>Λευεί</g>, acc. <g>-είν</g>, <g>ὁ</g> (Heb. <h n=\"H3878\">לֵוִי</h>),</f> <s><b>Levi</b>; <s n=\"1.\">the son of Jacob: <r v=\"Heb.7.5\"></r>, <r v=\"Heb.7.9\"></r>, <r v=\"Rev.7.7\"></r>.</s> <s n=\"2.\">Son of Melchi: <r v=\"Luke.3.24\"></r>.</s> <s n=\"3.\">Son of Simeon: <r v=\"Luke.3.29\"></r>.</s> <s n=\"4.\">Son of Alphæus (cf. <g>Μαθθαῖος</g>): <r v=\"Mark.2.14\"></r> (WH, mg., <g>Ἰάκωβον</g>), <r v=\"Luke.5.27\"></r>, <r v=\"Luke.5.29\"></r>.†</s> </s>"},"G3075":{"l":"λυμαίνομαι","o":1,"ar":"<f><o>λυμαίνομαι</o></f> <s n=\"1.\"><b>أهان</b>، <b>أساء المعاملة</b>: مع المنصوب، <r v=\"Acts.8.3\"></r>.</s> <s n=\"2.\">في السبعينية: <b>أفسد</b>، <b>نجّس</b> (<r v=\"Ezek.16.25\"></r>، <r v=\"Prov.23.8\"></r>، <r v=\"4Macc.18.8\"></r>، وفي مواضع أخرى).†</s>","en":"<f><o>λυμαίνομαι</o></f> <et> <e t=\"derivation\">(&lt; <g>λύμη</g>, <i>outrage</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7843\">שׁחת</h> pi., hi., also for <h n=\"H3765\">כִּרְסֵם</h>, etc.;]</e> </et> <s n=\"1.\"><b>to outrage</b>, <b>maltreat</b>: c. acc., <r v=\"Acts.8.3\"></r>.</s> <s n=\"2.\"><b>to corrupt</b>, <b>defile</b> (<r v=\"Ezek.16.25\"></r>, <r v=\"Prov.23.8\"></r>, <r v=\"4Macc.18.8\"></r>, al.).†</s>"},"G3086":{"l":"λυτρωτής","o":1,"ar":"<f><o>λυτρωτής</o>، <g>-οῦ, ὁ</g></f> <s><b>فادٍ</b>، <b>مخلّص</b>: <r v=\"Acts.7.35\"></r> (لا يرد في موضع آخر).†</s>","en":"<f><o>λυτρωτής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>λυτρόω</g>),</e> <e t=\"septuagint\">[in LXX: of God, <r v=\"Ps.19.14\"></r> <r v=\"Ps.78.35\"></r> (<h n=\"H1350\">גֹּאֵל</h>)*;]</e> </et> <s><b>a redeemer</b>, <b>deliverer</b>: <r v=\"Acts.7.35\"></r> (not found elsewhere).†</s>"},"G3033":{"l":"Λιβύη","o":1,"ar":"<f><o>Λιβύη</o>، <g>-ης, ἡ</g>،</f> <s><b>ليبية</b>: <r v=\"Acts.2.10\"></r>.†</s>","en":"<f><o>Λιβύη</o>, <g>-ης, ἡ</g>,</f> <s><b>Libya</b>: <r v=\"Acts.2.10\"></r>.†</s>"},"G3015":{"l":"λεπρός","o":9,"ar":"<f><o>λεπρός</o>، <g>-ά, -όν</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>ذو قشور</b>، <b>خشن</b>.</s> <s n=\"2.\"><b>أبرص</b>؛ غالبًا اسمًا، <g>ὁ λ.</g>، <b>الأبرص</b>: <r v=\"Matt.8.2\"></r>، <r v=\"Matt.10.8\"></r>، <r v=\"Matt.11.5\"></r>، <r v=\"Mark.1.40\"></r>، <r v=\"Luke.4.27\"></r>، <r v=\"Luke.7.22\"></r>، <r v=\"Luke.17.12\"></r>؛ عن سمعان الذي كان أبرص سابقًا، <r v=\"Matt.26.6\"></r>، <r v=\"Mark.14.3\"></r>.†</s>","en":"<f><o>λεπρός</o>, <g>-ά, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>λεπίς</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6879\">צָרוּעַ</h>, <h n=\"H6879\">מְצֹרָע</h>;]</e> </et> <s n=\"1.\">(in cl.) <b>scaly</b>, <b>rough</b>.</s> <s n=\"2.\"><b>leprous</b>; chiefly as subst., <g>ὁ λ.</g>, <b>a leper</b>: <r v=\"Matt.8.2\"></r> <r v=\"Matt.10.8\"></r> <r v=\"Matt.11.5\"></r>, <r v=\"Mark.1.40\"></r>, <r v=\"Luke.4.27\"></r> <r v=\"Luke.7.22\"></r> <r v=\"Luke.17.12\"></r>; of Simon, formerly a leper, <r v=\"Matt.26.6\"></r>, <r v=\"Mark.14.3\"></r>.†</s>"},"G3061":{"l":"λοιμός","o":2,"ar":"<f><o>λοιμός</o>، <g>-οῦ, ὁ</g>،</f> <s><b>وبأ</b>: جمع، <r v=\"Luke.21.11\"></r>؛ مجازيًا (كما في السبعينية: <r v=\"Ps.1.1\"></r>، <r v=\"Prov.21.24\"></r>، <r v=\"1Macc.15.21\"></r>، وفي مواضع أخرى)، عن الأشخاص، <b>مُفسِد، آفة</b>: <r v=\"Acts.24.5\"></r> (وأيضًا صفةً، <g>ἄνδρες λοιμοί</g>، <r v=\"1Macc.10.61\"></r>، وفي مواضع أخرى).†</s>","en":"<f><o>λοιμός</o>, <g>-οῦ, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3887\">לוּץ</h>, <h n=\"H6184\">עָרִיץ</h>, <h n=\"H1100\">בְּלִיַּעַל</h>, etc.;]</e> </et> <s><b>pestilence</b>: pl., <r v=\"Luke.21.11\"></r>; metaph. (as in cl.; LXX: <r v=\"Ps.1.1\"></r>, <r v=\"Prov.21.24\"></r>, <r v=\"1Macc.15.21\"></r>, al.), of persons, <b>a pest</b>: <r v=\"Acts.24.5\"></r> (also as adj., <g>ἄνδρες λοιμοί</g>, <r v=\"1Macc.10.61\"></r>, al.).†</s>"},"G3074":{"l":"λύκος","o":6,"ar":"<f><o>λύκος</o>، <g>-ου, ὁ</g>،</f> <s><b>ذئب</b>: <r v=\"Matt.10.16\"></r>، <r v=\"Luke.10.3\"></r>، <r v=\"John.10.12\"></r>؛ مجازيًا (كما في <r v=\"Ezek.22.27\"></r>، <r v=\"Zeph.3.3\"></r>، <r v=\"Jer.5.6\"></r>، وفي مواضع أخرى)، <r v=\"Matt.7.1\"></r>، <r v=\"Acts.20.29\"></r>.†</s>","en":"<f><o>λύκος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2061\">זְאֵב</h>;]</e> </et> <s><b>a wolf</b>: <r v=\"Matt.10.16\"></r>, <r v=\"Luke.10.3\"></r>, <r v=\"John.10.12\"></r>; fig. (as <r v=\"Ezek.22.27\"></r>, <r v=\"Zeph.3.3\"></r>, <r v=\"Jer.5.6\"></r>, al.), <r v=\"Matt.7.1\"></r>, <r v=\"Acts.20.29\"></r>.†</s>"},"G3052":{"l":"λόγιος","o":1,"ar":"<f>* <o>λόγιος</o>، <g>-ον</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>عالِم، متعلّم</b> (قارن <r v=\"Acts.18.24\"></r>).</s> <s n=\"2.\">في اليونانية المتأخرة: <b>فصيح</b>: <r v=\"Acts.18.24\"></r>.†</s>","en":"<f>* <o>λόγιος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>λόγος</g>),</e> </et> <s n=\"1.\">in cl., <b>learned</b> (<r v=\"Acts.18.24\"></r>, R, txt.).</s> <s n=\"2.\">In late Gk., <b>eloquent</b>: <r v=\"Acts.18.24\"></r> (v. Page, in l.; Field, <i>Notes</i>, 129).†</s>"},"G3095":{"l":"μαγία","o":1,"ar":"<f>* <o>μαγία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>علم المجوس</b>.</s> <s n=\"2.\"><b>سِحر</b>: جمع، <b>فنون السحر</b>، <b>أعمال سحرية</b>: <r v=\"Acts.8.11\"></r>.†</s>","en":"<f>* <o>μαγία</o> (Rec. <g>-εία</g>), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>μάγος</g>),</e> </et> <s n=\"1.\"><b>the lore of the Magians</b> (Plat.).</s> <s n=\"2.\"><b>magic</b>: pl., <b>magic arts</b>, <b>sorceries</b>: <r v=\"Acts.8.11\"></r>.†</s>"},"G3057":{"l":"λόγχη","o":1,"ar":"<f><o>λόγχη</o>، <g>-ης, ἡ</g>،</f> <s n=\"1.\"><b>سِنان الرمح</b>.</s> <s n=\"2.\"><b>حربة</b>، <b>رمح</b>: <r v=\"Matt.27.49\"></r>، <r v=\"John.19.34\"></r>.†</s>","en":"<f><o>λόγχη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7420\">רֹמַח</h>, etc.;]</e> </et> <s n=\"1.\"><b>a spear-head</b>.</s> <s n=\"2.\"><b>a lance</b>, <b>spear</b>: <r v=\"Matt.27.49\"></r> (|[WH]|, R, mg.), <r v=\"John.19.34\"></r>.†</s>"},"G3072":{"l":"Λυκαονιστί","o":1,"ar":"<f><o>Λυκαονιστί</o>،</f> ظرف، <s><b>بلغة ليكأونية</b>: <r v=\"Acts.14.11\"></r>.†</s>","en":"<f><o>Λυκαονιστί</o>,</f> adv., <s><b>in Lycaonian</b> (speech): <r v=\"Acts.14.11\"></r>.†</s>"},"G3078":{"l":"Λυσανίας","o":1,"ar":"<f><o>Λυσανίας</o>، <g>-ου, ὁ</g>،</f> <s><b>ليسانيوس</b>: <r v=\"Luke.3.1\"></r>.†</s>","en":"<f><o>Λυσανίας</o>, <g>-ου, ὁ</g>,</f> <s><b>Lysanias</b>: <r v=\"Luke.3.1\"></r>.†</s>"},"G3014":{"l":"λέπρα","o":4,"ar":"<f><o>λέπρα</o>، <g>-ας, ἡ</g></f> <s><b>برص</b>: <r v=\"Matt.8.3\"></r>، <r v=\"Mark.1.42\"></r>، <r v=\"Luke.5.12\"></r>، <r v=\"Luke.5.13\"></r>.†</s>","en":"<f><o>λέπρα</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λεπρός</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6883\">צָרַעַת</h>;]</e> </et> <s><b>leprosy</b>: <r v=\"Matt.8.3\"></r>, <r v=\"Mark.1.42\"></r>, <r v=\"Luke.5.12\"></r>, <r v=\"Luke.5.13\"></r>.†</s>"},"G3026":{"l":"λῆρος","o":1,"ar":"<f>** <o>λῆρος</o>، <g>-ου, ὁ</g>،</f> <s><b>كلام سخيف</b>، <b>هذيان</b>: <r v=\"Luke.24.11\"></r>.†</s>","en":"<f>** <o>λῆρος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.5.10\"></r>*;]</e> </et> <s><b>silly talk</b>, <b>nonsense</b>: <r v=\"Luke.24.11\"></r>.†</s>"},"G3097":{"l":"μάγος","o":6,"ar":"<f><o>μάγος</o>، <g>-ου, ὁ</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: واحد من الـ<g>Μάγοι</g>، وهم قبيلة ميدية.</s> <s n=\"2.\"><b>مجوسي</b>، واحد من طبقة كهنوتية، ميدية الأصل، يبدو أنهم انضمّوا إلى الديانة الفارسية مع احتفاظهم ببعض معتقداتهم القديمة: <r v=\"Matt.2.1\"></r>، <r v=\"Matt.2.7\"></r>، <r v=\"Matt.2.16\"></r>.</s> <s n=\"3.\"><b>ساحر</b>، <b>عرّاف</b>: <r v=\"Acts.13.6\"></r>، <r v=\"Acts.13.8\"></r> (قارن <r v=\"Wis.17.7\"></r>، <r v=\"Acts.8.9\"></r>، <r v=\"Acts.8.11\"></r>).†</s>","en":"<f><o>μάγος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H825\">אַשָּׁף</h>, <r v=\"Dan.2.2\"></r>, <r v=\"Dan.2.10\"></r>, al. (cf. <h n=\"H7227\">רַב־מָג</h> <i>chief magian</i>, <r v=\"Jer.39.3\"></r>, <r v=\"Jer.39.13\"></r>);]</e> </et> <s n=\"1.\">one of the <g>Μάγοι</g>, a Median tribe (Hdt).</s> <s n=\"2.\"><b>a Magian</b>, one of a sacred caste, originally Median, who seem to have conformed to the Persian religion, while retaining some of their old beliefs (v. <i>DB</i>, I vol., 565 f.; <i>DB</i>, iii, 203 ff.): <r v=\"Matt.2.1\"></r>, <r v=\"Matt.2.7\"></r>, <r v=\"Matt.2.16\"></r>.</s> <s n=\"3.\"><b>a wizard</b>, <b>sorcerer</b>: <r v=\"Acts.13.6\"></r>, <r v=\"Acts.13.8\"></r> (cf. <r v=\"Wis.17.7\"></r>, <r v=\"Acts.8.9\"></r>, <r v=\"Acts.8.11\"></r>).†</s>"},"G3094":{"l":"Μαγδαληνός","o":12,"ar":"<f><o>Μαγδαληνός</o>، <g>-ά, όν</g>،</f> <s><b>المجدلية</b>، <b>من مجدل</b>: <g>Μαρία</g> (انظره) <g>ἡ</g>، <r v=\"Matt.27.56\"></r>، <r v=\"Matt.27.61\"></r> <r v=\"Matt.28.1\"></r>، <r v=\"Mark.15.40\"></r>، <r v=\"Mark.15.47\"></r> <r v=\"Mark.16.1\"></r>، [<r v=\"Mark.16.9\"></r>]، <r v=\"Luke.8.2\"></r> <r v=\"Luke.24.10\"></r>، <r v=\"John.19.25\"></r> <r v=\"John.20.1\"></r>، <r v=\"John.20.18\"></r>.†</s>","en":"<f><o>Μαγδαληνός</o>, <g>-ά, όν</g>,</f> <s><b>Magdalene</b>, <b>of Magdala</b>: <g>Μαρία</g> (q.v.) <g>ἡ</g> MM., <r v=\"Matt.27.56\"></r>, <r v=\"Matt.27.61\"></r> <r v=\"Matt.28.1\"></r>, <r v=\"Mark.15.40\"></r>, <r v=\"Mark.15.47\"></r> <r v=\"Mark.16.1\"></r>, [<r v=\"Mark.16.9\"></r>], <r v=\"Luke.8.2\"></r> <r v=\"Luke.24.10\"></r>, <r v=\"John.19.25\"></r> <r v=\"John.20.1\"></r>, <r v=\"John.20.18\"></r>.†</s>"},"G3016":{"l":"λεπτός","o":3,"ar":"<f>* <o>λεπτός</o>، <g>-ή, -όν</g></f> <s n=\"1.\"><b>مقشور</b>.</s> <s n=\"2.\"><b>دقيق</b>، <b>رقيق</b>، <b>صغير</b>، <b>خفيف</b>؛ ومن ثمّ، في اليونانية المتأخرة، اسمًا <g>τὸ λ.</g>، <b>قطعة نقود صغيرة، فَلْس</b> (ثُمن الـ<i>آس</i> الروماني؛ في الترجمة المعتمدة <i>فلس</i>): <r v=\"Mark.12.42\"></r>، <r v=\"Luke.12.59\"></r> <r v=\"Luke.21.2\"></r>.†</s>","en":"<f>* <o>λεπτός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(<g>λέπω</g>, <i>to peel</i>),</e> </et> <s n=\"1.\"><b>peeled</b>.</s> <s n=\"2.\"><b>fine</b>, <b>thin</b>, <b>small</b>, <b>light</b>; hence, in late Gk., as subst. <g>τὸ λ.</g>, <b>a small coin</b> (one-eighth of an <i>as</i>, AV, <i>mite</i>): <r v=\"Mark.12.42\"></r>, <r v=\"Luke.12.59\"></r> <r v=\"Luke.21.2\"></r>.†</s>"},"G3069":{"l":"λύδδα","o":3,"ar":"<f><o>λύδδα</o>، <g>-ας</g> (<r v=\"Acts.9.38\"></r>)، <g>ἡ</g> و<g>λύδδα, -ων, τά</g> (<r v=\"Acts.9.32\"></r>، <r v=\"Acts.9.35\"></r>)، (بالعبرية <h n=\"H3850\">לֹד</h>)،</f> <s><b>لُدّة</b> (<i>اللدّ</i> حاليًا): <r v=\"Acts.9.32\"></r>، <r v=\"Acts.9.35\"></r>، <r v=\"Acts.9.38\"></r>.†</s>","en":"<f><o>λύδδα</o>, <g>-ας</g> (<r v=\"Acts.9.38\"></r>, <g>-ης</g> Rec.), <g>ἡ</g> and <g>λύδδα, -ων, τά</g> (<r v=\"Acts.9.32\"></r>, <r v=\"Acts.9.35\"></r>; <g>-αν</g>, Rec.), (Heb. <h n=\"H3850\">לֹד</h>),</f> <s><b>Lydda</b> (modern <i>Ludd</i>): <r v=\"Acts.9.32\"></r>, <r v=\"Acts.9.35\"></r>, <r v=\"Acts.9.38\"></r>.†</s>"},"G3099":{"l":"Μαδιάμ","o":1,"ar":"<f><o>Μαδιάμ</o>، <g>ὁ</g>، لا يُصرَّف (بالعبرية <h n=\"H4080\">מִדְיָן</h>)،</f> <s><b>مديان</b>؛ <s n=\"1.\">ابن إبراهيم (<r v=\"Gen.25.2\"></r>).</s> <s n=\"2.\">قبيلة عربية (<r v=\"Gen.36.35\"></r>، <r v=\"Ps.83.9\"></r>، وفي مواضع أخرى).</s> <s n=\"3.\"><g>γῆ Μ.</g> (بالعبرية <h n=\"H776\">אֶרֶץ</h> <h n=\"H4080\">מִדְיָן</h>)، <b>أرض مديان</b> (<r v=\"Exod.2.15\"></r>، وفي مواضع أخرى): <r v=\"Acts.7.29\"></r>.†</s> </s>","en":"<f><o>Μαδιάμ</o>, <g>ὁ</g>, indecl. (Heb. <h n=\"H4080\">מִדְיָן</h>),</f> <s><b>Midian</b>; <s n=\"1.\">son of Abraham (<r v=\"Gen.25.2\"></r>).</s> <s n=\"2.\">An Arabian tribe (<r v=\"Gen.36.35\"></r>, <r v=\"Ps.83.9\"></r>, al).</s> <s n=\"3.\"><g>γῆ Μ.</g> (Heb. <h n=\"H776\">אֶרֶץ</h> <h n=\"H4080\">מִדְיָן</h>), <b>the land of Midian</b> (<r v=\"Exod.2.15\"></r>, al.): <r v=\"Acts.7.29\"></r>.†</s> </s>"},"G3093":{"l":"Μαγδαλά","o":1,"ar":"<f><o>Μαγδαλά</o> (بالآرامية <h n=\"????\">מַגְדְֺּלָא</h> = بالعبرية <h n=\"H4026\">מִגְדֹּל</h>، التي تُرجمت في <r v=\"Josh.15.37\"></r> بـ<g>Μαγαδά</g>)،</f> <s><b>مجدل</b>: <r v=\"Matt.15.39\"></r> (قراءة النص المستلَم بدل <g>Μαγαδάν</g>، انظره).†</s>","en":"<f><o>Μαγδαλά</o> (Aram. <h n=\"????\">מַגְדְֺּלָא</h> = Heb. <h n=\"H4026\">מִגְדֹּל</h>, which in <r v=\"Josh.15.37\"></r> B is rendered <g>Μαγαδά</g>),</f> <s><b>Magdala</b>: <r v=\"Matt.15.39\"></r> (Rec. for <g>Μαγαδάν</g>, q.v.).†</s>"},"G3092":{"l":"Μαάθ","o":1,"ar":"<f><o>Μαάθ</o>، <g>ὁ</g>، لا يُصرَّف،</f> <s><b>مآث</b>: <r v=\"Luke.3.26\"></r>.†</s>","en":"<f><o>Μαάθ</o>, <g>ὁ</g>, indecl.,</f> <s><b>Maath</b>: <r v=\"Luke.3.26\"></r>.†</s>"},"G3038":{"l":"λιθόστρωτος","o":1,"ar":"<f><o>λιθό-στρωτος</o>، <g>-ον</g></f> <s><b>مرصوف بالحجارة</b>، خاصةً عن الفسيفساء (<r v=\"Song.3.10\"></r>)؛ اسمًا، <g>τὸ λ.</g>، <b>البلاط (رصيف من الفسيفساء)</b>: <r v=\"John.19.13\"></r> (قارن <g>Γαββαθᾶ</g>).†</s>","en":"<f><o>λιθό-στρωτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>στρώννυμι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Chr.7.3\"></r>, <r v=\"Ezra.1.6\"></r>, <r v=\"Song.3.10\"></r> (<h n=\"H7531\">רִצְפָּה</h>, <h n=\"H7528\">רָצַף</h>)*;]</e> </et> <s><b>paved with stones</b>, esp. of tessallated work (<r v=\"Song.3.10\"></r>); as subst., <g>τὸ λ.</g>, <b>a tessallated pavement</b>: <r v=\"John.19.13\"></r> (cf. <g>Γαββαθᾶ</g>).†</s>"},"G3012":{"l":"λέντιον","o":2,"ar":"<f>*† <o>λέντιον</o>، <g>-ου, τό</g> (من اللاتينية <l>linteum</l>)،</f> <s><b>قطعة كتّان</b>، <b>منشفة</b>: <r v=\"John.13.4\"></r>، <r v=\"John.13.5\"></r>.†</s>","en":"<f>*† <o>λέντιον</o>, <g>-ου, τό</g> (Lat. <l>linteum</l>),</f> <s><b>a linen cloth</b>, <b>towel</b>: <r v=\"John.13.4\"></r>, <r v=\"John.13.5\"></r>.†</s>"},"G3040":{"l":"λιμήν","o":2,"ar":"<f><o>λιμήν</o>، <g>-ένος, ὁ</g>،</f> <s><b>ميناء</b>، <b>مرفأ</b>: <r v=\"Acts.27.8\"></r>، <r v=\"Acts.27.12\"></r> (قارن <g>Καλοὶ Λιμένες</g>).†</s>","en":"<f><o>λιμήν</o>, <g>-ένος, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.107.30\"></r> (<h n=\"H4231\">מָחוֹז</h>), <r v=\"Ps.107.35\"></r>, <r v=\"1Esd.5.55\"></r>, I, II, IV Mac<i>7</i>*;]</e> </et> <s><b>a harbour</b>, <b>haven</b>: <r v=\"Acts.27.8\"></r>, <r v=\"Acts.27.12\"></r> (cf. <g>Καλοὶ Λιμένες</g>).†</s>"}});A.got[30]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});